// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"bacitracin-neomycin":{"wirkmechanismus":"Zwei Antibiotika mit sich ergänzender Wirkung töten Bakterien auf der Haut ab. Bacitracin hemmt den Aufbau der Bakterienzellwand und wirkt vor allem gegen grampositive Keime wie Staphylokokken und Streptokokken. Neomycin, ein Aminoglykosid, blockiert die Eiweissherstellung am bakteriellen Ribosom und erfasst zusätzlich viele gramnegative Keime. Die Kombination wirkt bakterizid (abtötend), und Resistenzen entstehen seltener als mit einem Wirkstoff allein.","nebenwirkungen":{"unbekannt":["Allergische Hautreaktionen: Rötung, Juckreiz, Trockenheit, Ausschlag, Kontaktekzem (Neomycin-Allergie)","Schwere allergische Reaktionen (Anaphylaxie)","Kreuzallergie mit anderen Aminoglykosiden","Bei grossflächiger Anwendung oder auf offener Haut: Nierenschäden, Hörschäden und Gleichgewichtsstörungen","Muskelschwäche durch Hemmung der Nerv-Muskel-Übertragung bei Aufnahme ins Blut"]},"schwangerschaft":"Nur kleinflächig und nach ärztlicher Abwägung: Aminoglykoside können nach Aufnahme ins Blut das Gehör des Ungeborenen schädigen.","stillzeit":"Kleinflächige Anwendung nach Abwägung möglich; nicht auf die Brust auftragen.","hinweise":["Nur auf kleine Hautflächen und kurzzeitig anwenden; ohne Besserung nach wenigen Tagen ärztlich kontrollieren lassen.","Bei Juckreiz, Rötung oder Verschlechterung absetzen – möglicherweise eine Neomycin-Allergie, die bei künftigen Behandlungen angegeben werden sollte.","Nicht in die Augen und nicht in den Gehörgang bei verletztem Trommelfell bringen."],"darreichung":["Salbe","Puder"]},"baclofen":{"wirkmechanismus":"Entspannt krankhaft verkrampfte Muskeln, indem es überschiessende Nervenreflexe im Rückenmark dämpft. Baclofen ist ein Abkömmling des Botenstoffs GABA und aktiviert GABA-B-Rezeptoren. Dadurch wird die Freisetzung erregender Neurotransmitter gehemmt und die Übertragung mono- und polysynaptischer Reflexe im Rückenmark vermindert. Baclofen wird grösstenteils unverändert über die Nieren ausgeschieden.","nebenwirkungen":{"sehrHaeufig":["Müdigkeit, Schläfrigkeit (Sedierung)","Übelkeit"],"haeufig":["Benommenheit, Schwindel, Kopfschmerzen","Verwirrtheit, Euphorie, Depression, Halluzinationen, Albträume, Schlaflosigkeit","Muskelschwäche, Gangunsicherheit (Ataxie), Zittern, Muskelschmerzen","Atemdepression (abgeschwächte Atmung)","Sehstörungen, Augenzittern (Nystagmus)","Blutdruckabfall","Mundtrockenheit, Erbrechen, Verstopfung, Durchfall","Vermehrtes Wasserlassen, Bettnässen, vermehrtes Schwitzen, Hautausschlag"],"selten":["Kribbeln (Parästhesien), Sprechstörungen, Geschmacksstörungen","Bauchschmerzen, erhöhte Leberwerte","Harnverhalt, Erektionsstörungen"],"sehrSelten":["Unterkühlung (Hypothermie)"],"unbekannt":["Entzugssymptome nach abruptem Absetzen (Halluzinationen, Krampfanfälle, Fieber, Muskelsteifheit; bei der Pumpe lebensbedrohlich)","Langsamer Puls (Bradykardie)","Blutzuckeranstieg","Schlafapnoe","Suizidgedanken und Suizidversuche"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit nach ärztlicher Abwägung; nach der Geburt sind Entzugskrämpfe beim Neugeborenen beschrieben.","stillzeit":"Geht bei Einnahme als Tablette nur in sehr geringen Mengen in die Muttermilch über; Stillen nach ärztlicher Abwägung möglich.","hinweise":["Nicht abrupt absetzen, sondern langsam ausschleichen – sonst Entzugssymptome bis zu Krampfanfällen. Bei der Pumpe die Nachfülltermine strikt einhalten.","Alkohol meiden.","Kann Müdigkeit, Schwindel und Sehstörungen verursachen – Vorsicht beim Autofahren.","Bei eingeschränkter Nierenfunktion deutlich niedriger dosieren; die Dosis wird langsam gesteigert."],"darreichung":["Tabletten","Intrathekale Injektions- bzw. Infusionslösung"]},"baldrian":{"wirkmechanismus":"Wirkt mild beruhigend und erleichtert das Einschlafen. Die Wirkung beruht auf dem Zusammenspiel mehrerer Inhaltsstoffe der Baldrianwurzel; diskutiert werden vor allem eine Verstärkung der hemmenden GABA-Signale im Gehirn (Valerensäure moduliert GABA-A-Rezeptoren) sowie Wirkungen an Adenosin-Rezeptoren. Der genaue Mechanismus ist nicht vollständig geklärt.","nebenwirkungen":{"unbekannt":["Magen-Darm-Beschwerden (z. B. Übelkeit, Bauchkrämpfe)","Überempfindlichkeitsreaktionen der Haut"]},"schwangerschaft":"Keine ausreichenden Daten; in der Schwangerschaft nicht empfohlen.","stillzeit":"Keine ausreichenden Daten; in der Stillzeit nicht empfohlen.","hinweise":["Bei Einschlafstörungen etwa eine halbe bis eine Stunde vor dem Zubettgehen einnehmen.","Die volle Wirkung entwickelt sich oft erst nach 2–4 Wochen regelmässiger Einnahme.","Kann die Reaktionsfähigkeit beeinträchtigen; Alkohol meiden.","Bessern sich die Beschwerden nach 2 Wochen nicht oder verschlimmern sie sich, ärztlichen Rat einholen."],"darreichung":["Filmtabletten","Dragées","Tropfen","Tee"]},"baldrian-hopfen":{"wirkmechanismus":"Wirkt mild beruhigend und erleichtert das Einschlafen. Inhaltsstoffe der Baldrianwurzel wie die Valerensäure verstärken vermutlich die hemmenden GABA-Signale im Gehirn; Hopfen wirkt ergänzend beruhigend. Für den Kombinationsextrakt werden zudem Wirkungen an Adenosin- und Melatoninrezeptoren diskutiert. Der genaue Mechanismus ist nicht vollständig geklärt.","nebenwirkungen":{"unbekannt":["Magen-Darm-Beschwerden (z. B. Übelkeit, Bauchkrämpfe)","Überempfindlichkeitsreaktionen der Haut"]},"schwangerschaft":"Keine ausreichenden Daten; in der Schwangerschaft nicht empfohlen.","stillzeit":"Keine ausreichenden Daten; in der Stillzeit nicht empfohlen.","hinweise":["Bei Einschlafstörungen etwa eine halbe bis eine Stunde vor dem Zubettgehen einnehmen.","Die volle Wirkung entwickelt sich oft erst nach 2–4 Wochen regelmässiger Einnahme.","Kann die Reaktionsfähigkeit beeinträchtigen; Alkohol meiden.","Bessern sich die Beschwerden nach 2 Wochen nicht oder verschlimmern sie sich, ärztlichen Rat einholen."],"darreichung":["Filmtabletten"]},"baloxavir-marboxil":{"wirkmechanismus":"Bremst die Vermehrung von Grippeviren im Körper. Baloxavir marboxil ist eine Vorstufe (Prodrug), die im Körper zur wirksamen Baloxavirsäure umgewandelt wird. Diese hemmt die Cap-abhängige Endonuklease in der PA-Untereinheit der viralen Polymerase. Das Virus kann dadurch keine «Kappen» von zellulären Boten-RNAs abspalten («cap-snatching») und seine Gene nicht mehr ablesen lassen. Wegen der sehr langen Halbwertszeit genügt eine einzige Dosis.","nebenwirkungen":{"unbekannt":["Überempfindlichkeitsreaktionen bis Anaphylaxie","Hautausschlag, Nesselsucht, Angioödem (Schwellung von Haut und Schleimhäuten), Erythema multiforme","Durchfall, Erbrechen","Blutiger Durchfall, Teerstuhl, Kolitis (Darmentzündung)","Verhaltensauffälligkeiten"]},"schwangerschaft":"Nur wenige Daten. Vorsichtshalber soll Baloxavir in der Schwangerschaft vermieden werden.","stillzeit":"Nicht bekannt, ob Baloxavir beim Menschen in die Muttermilch übergeht (bei Tieren ja). Ein Risiko für den Säugling kann nicht ausgeschlossen werden – ärztlich abwägen.","hinweise":["Einmalige Einnahme möglichst früh, spätestens 48 Stunden nach Beginn der Grippesymptome.","Nicht zusammen mit Milchprodukten, calciumangereicherten Getränken, Säurebindern, Abführmitteln oder Mineralstoffpräparaten (Calcium, Eisen, Magnesium, Zink, Selen) einnehmen.","Ersetzt die jährliche Grippeimpfung nicht."],"darreichung":["Filmtabletten"]},"baricitinib":{"wirkmechanismus":"Unterbricht in den Zellen die Signalweiterleitung zahlreicher Entzündungsbotenstoffe. Baricitinib hemmt selektiv und reversibel die Januskinasen JAK1 und JAK2, die die Signale von Zytokin- und Wachstumsfaktor-Rezeptoren (z. B. für Interleukin-6 und Interferone) über STAT-Proteine in den Zellkern weiterleiten. Dadurch werden Gelenkentzündung, Juckreiz und Hautentzündung sowie die gegen die Haarwurzeln gerichtete Immunreaktion gedämpft.","nebenwirkungen":{"sehrHaeufig":["Infektionen der oberen Atemwege","Erhöhtes LDL-Cholesterin"],"haeufig":["Gürtelrose (Herpes zoster), Lippenherpes","Magen-Darm-Infekt, Harnwegsinfekte","Lungenentzündung","Thrombozytose (vermehrte Blutplättchen)","Kopfschmerzen","Übelkeit, Bauchschmerzen","Erhöhte Leberwerte (ALT)","Ausschlag, Akne"],"gelegentlich":["Neutropenie (Mangel an weissen Blutkörperchen)","Erhöhte Triglyceride, Gewichtszunahme","Tiefe Venenthrombose und Lungenembolie","Divertikulitis","Gesichtsschwellung, Nesselsucht","Erhöhte CK (Muskelenzym)"],"unbekannt":["Schwere Herz-Kreislauf-Ereignisse (Herzinfarkt, Schlaganfall)","Bösartige Erkrankungen (z. B. Lymphome, Lungenkrebs, heller Hautkrebs)","Magen-Darm-Perforation (Durchbruch)","Tuberkulose und opportunistische Infektionen"]},"schwangerschaft":"Kontraindiziert. Frauen im gebärfähigen Alter müssen während und mindestens 1 Woche nach der Behandlung zuverlässig verhüten.","stillzeit":"Nicht anwenden bzw. nicht stillen während der Behandlung.","hinweise":["Blutbild, Leberwerte und Blutfette werden vor Beginn und regelmässig kontrolliert.","Bei plötzlicher Atemnot, Brustschmerzen oder einem geschwollenen, schmerzhaften Bein sofort ärztliche Hilfe holen (Thrombose, Lungenembolie).","Bei Gürtelrose (schmerzhafter Bläschenausschlag) oder anderen Infektzeichen rasch ärztlich abklären lassen.","Keine Lebendimpfungen; Impfungen (inkl. Gürtelrose) möglichst vor Beginn nachholen."],"darreichung":["Filmtabletten"]},"basiliximab":{"wirkmechanismus":"Verhindert, dass sich die Abwehrzellen nach einer Transplantation gegen das neue Organ vermehren. Basiliximab ist ein chimärer (Maus/Mensch) monoklonaler Antikörper, der an die Alpha-Kette des Interleukin-2-Rezeptors (CD25) bindet. Dieser Rezeptor wird nur auf aktivierten T-Lymphozyten gebildet; seine Blockade unterbindet das Wachstumssignal von Interleukin-2 und damit die Vermehrung der T-Zellen, die die Abstossung tragen. Mit zwei Gaben (am Operationstag und am 4. Tag danach) bleibt der Rezeptor etwa 4–6 Wochen blockiert.","nebenwirkungen":{"sehrHaeufig":["Verstopfung, Übelkeit, Durchfall","Harnwegs- und Atemwegsinfekte","Bluthochdruck","Periphere Ödeme (Wassereinlagerungen)","Kopfschmerzen und Schmerzen","Anämie (Blutarmut)","Erhöhtes Kalium und Cholesterin, erniedrigtes Phosphat","Wundheilungsstörungen nach der Operation"],"sehrSelten":["Schwere Überempfindlichkeitsreaktionen (Anaphylaxie) mit Ausschlag, Atemnot, Bronchospasmus, Lungenödem, Herz- oder Atemversagen","Kapillarlecksyndrom (Flüssigkeitsaustritt aus den Gefässen)","Zytokin-Freisetzungssyndrom"]},"schwangerschaft":"Kontraindiziert. Frauen im gebärfähigen Alter müssen während und bis 16 Wochen nach der letzten Dosis zuverlässig verhüten.","stillzeit":"Kontraindiziert; auch bis 16 Wochen nach der letzten Dosis nicht stillen.","hinweise":["Wird im Spital von transplantationserfahrenen Fachpersonen gegeben: erste Dosis kurz vor der Operation, zweite Dosis 4 Tage danach.","Die sehr häufigen Beschwerden traten in Studien unter Placebo etwa gleich oft auf; sie hängen meist mit der Transplantation und den übrigen Medikamenten zusammen.","Bei einer späteren erneuten Behandlung (z. B. zweite Transplantation) ist das Risiko für Überempfindlichkeitsreaktionen erhöht."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektions- bzw. Infusionslösung"]},"bcg-intravesikal":{"wirkmechanismus":"Löst in der Blasenwand eine starke örtliche Entzündung aus, mit der das Immunsystem Krebszellen bekämpft. Die abgeschwächten lebenden Bakterien (Mycobacterium bovis, BCG) haften an der Blasenschleimhaut und werden von Schleimhaut- und Tumorzellen aufgenommen. Darauf wandern Granulozyten, Makrophagen und T-Zellen ein und setzen Botenstoffe wie Interleukin-2, Interferon gamma und TNF-alpha frei, die Tumorzellen zerstören. Der genaue Mechanismus ist nicht vollständig geklärt.","nebenwirkungen":{"sehrHaeufig":["Blasenentzündung (Zystitis) mit Schmerzen und Brennen beim Wasserlassen","Häufiger oder dringender Harndrang","Blut im Urin (Hämaturie)","Grippeähnliche Beschwerden: Fieber, Schüttelfrost, Unwohlsein, Müdigkeit"],"haeufig":["Übelkeit, Erbrechen, Appetitlosigkeit","Gelenk- und Muskelschmerzen","Harnwegsinfektion"],"gelegentlich":["Ausbreitung der BCG-Infektion im Körper bis BCG-Sepsis (lebensbedrohlich)"],"unbekannt":["Granulomatöse Entzündung von Prostata, Nebenhoden oder Hoden","Granulomatöse Lungen- oder Leberentzündung","Schrumpfblase, Harnleiterverengung, Nierenabszess","Infektion von Gefässen, Aneurysmen oder Prothesen durch BCG","Reaktive Gelenkentzündung, Augenentzündung","Blutbildveränderungen","Überempfindlichkeitsreaktionen, Hautausschlag"]},"schwangerschaft":"Nicht anwenden; Erfahrungen fehlen.","stillzeit":"Nicht anwenden bzw. abstillen; Erfahrungen fehlen.","hinweise":["4 Stunden vor der Instillation wenig trinken; die Lösung möglichst 2 Stunden in der Blase behalten.","Während 6 Stunden nach der Instillation im Sitzen urinieren, danach Hände und Genitalbereich waschen und den Urin gemäss Anleitung desinfizieren.","Bei Fieber über 39 °C oder grippeähnlichen Beschwerden länger als 48 Stunden sofort ärztlich melden.","Während einer Woche nach der Instillation beim Geschlechtsverkehr Kondome verwenden."],"darreichung":["Pulver zur Herstellung einer Suspension zur Anwendung in der Harnblase"]},"beclometason":{"wirkmechanismus":"Hemmt die Entzündung in den Bronchien und macht sie weniger reizbar. Beclometasondipropionat ist ein Prodrug: in der Lunge wird es durch Esterasen zum stark wirksamen Beclometason-17-monopropionat gespalten, das an Glukokortikoid-Rezeptoren bindet. Dadurch werden die Bildung von Entzündungsbotenstoffen und die Einwanderung von Entzündungszellen vermindert. Die Wirkung baut sich über Tage bis Wochen auf; es ist kein Mittel gegen akute Anfälle.","nebenwirkungen":{"haeufig":["Mundsoor (Pilzinfektion in Mund und Rachen)","Heiserkeit","Rachenreizung","Lungenentzündung (bei COPD unter Kombipräparaten)"],"gelegentlich":["Überempfindlichkeitsreaktionen der Haut (Ausschlag, Nesselsucht, Juckreiz, Rötung)"],"sehrSelten":["Angioödem (Schwellung von Augen, Gesicht, Lippen, Rachen), Atemnot, Anaphylaxie","Paradoxer Bronchospasmus","Systemische Kortisonwirkungen: Nebennierenunterdrückung, Cushing-Syndrom, Wachstumsverzögerung bei Kindern, Abnahme der Knochendichte, grauer und grüner Star"],"unbekannt":["Psychomotorische Überaktivität, Schlafstörungen, Angst, Depression, Aggressivität (v. a. bei Kindern)","Verschwommensehen"]},"schwangerschaft":"Nur nach ärztlicher Nutzen-Risiko-Abwägung; eine gute Asthmakontrolle ist für Mutter und Kind wichtig, und mit inhaliertem Beclometason liegen langjährige Erfahrungen vor.","stillzeit":"Ein Übergang in die Muttermilch in geringen Mengen ist anzunehmen; bei inhalierten Dosen ist ein Risiko für den Säugling unwahrscheinlich – Anwendung nach ärztlicher Abwägung.","hinweise":["Regelmässig anwenden, auch bei Beschwerdefreiheit; die volle Wirkung tritt erst nach einigen Tagen ein.","Nach dem Inhalieren den Mund ausspülen oder vor dem Essen inhalieren – beugt Mundsoor und Heiserkeit vor.","Nicht abrupt absetzen; nach Umstellung von Kortisontabletten bei Operationen oder schweren Infekten die frühere Kortisonbehandlung angeben.","Bei Kindern unter Langzeittherapie das Längenwachstum regelmässig kontrollieren lassen."],"darreichung":["Dosieraerosol","Atemzugausgelöstes Dosieraerosol (Autohaler)","Pulver zur Inhalation (Kombipräparat)"]},"beclometason-formoterol-glycopyrronium":{"wirkmechanismus":"Kombiniert Entzündungshemmung mit zweifacher Bronchienerweiterung. Beclometasondipropionat ist ein Prodrug, das in der Lunge zum aktiven Beclometason-17-monopropionat umgewandelt wird und über den Glukokortikoidrezeptor entzündungshemmend wirkt. Formoterol stimuliert Beta-2-Rezeptoren und entspannt rasch die Bronchialmuskulatur; Glycopyrronium blockiert Muskarinrezeptoren (M3) und verhindert die durch Acetylcholin vermittelte Verengung. Die extrafeinen Partikel erreichen auch die kleinen Atemwege.","nebenwirkungen":{"haeufig":["Lungenentzündung (Pneumonie) bei COPD","Candidose (Pilzbefall) in Mund und Rachen","Rachenentzündung (Pharyngitis), Nasopharyngitis","Harnwegsinfekt","Kopfschmerzen","Heiserkeit (Dysphonie)"],"gelegentlich":["Hypokaliämie (Kaliummangel), Hyperglykämie (erhöhter Blutzucker)","Vorhofflimmern, Tachykardie, Herzklopfen","QT-Verlängerung im EKG","Zittern, Schwindel, Unruhe","Husten, Rachenreizung","Mundtrockenheit","Muskelkrämpfe","Harnverhalt, Schmerzen beim Wasserlassen"],"selten":["Überempfindlichkeitsreaktionen, auch Angioödem (Schwellung von Gesicht, Lippen, Rachen)","Paradoxer Bronchospasmus","Angina pectoris","Schlaflosigkeit"],"sehrSelten":["Nebennierenrindensuppression (Nebennierenunterfunktion)","Glaukom (grüner Star)","Thrombozytopenie (Mangel an Blutplättchen)"],"unbekannt":["Verschwommenes Sehen","Psychomotorische Unruhe, Angst, Depression, Aggressivität, Verhaltensänderungen"]},"schwangerschaft":"Nur begrenzte Erfahrungen; nur anwenden, wenn der erwartete Nutzen das mögliche Risiko für das Kind überwiegt. Formoterol kann die Wehen hemmen.","stillzeit":"Nicht bekannt, ob alle Wirkstoffe in die Muttermilch übergehen; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Morgens und abends regelmässig inhalieren; eine Inhalierhilfe (Spacer) kann die Anwendung erleichtern.","Nach dem Inhalieren den Mund ausspülen oder die Zähne putzen (Vorbeugung gegen Pilzbefall und Heiserkeit).","Nicht für akute Atemnot – dafür ein rasch wirksames Bedarfsspray verwenden.","Nicht eigenmächtig absetzen; Fieber, verfärbter Auswurf und zunehmende Atemnot können auf eine Lungenentzündung hinweisen – ärztlich abklären."],"darreichung":["Dosieraerosol"]},"bedaquilin":{"wirkmechanismus":"Tötet Tuberkulosebakterien ab, indem es ihnen die Energieversorgung entzieht. Bedaquilin hemmt spezifisch die ATP-Synthase der Mykobakterien (Untereinheit c), sodass die Bakterien kein ATP mehr bilden können. Dieser Wirkmechanismus unterscheidet sich von dem aller anderen Tuberkulosemittel, deshalb besteht keine Kreuzresistenz. Bedaquilin hat eine sehr lange Halbwertszeit von mehreren Monaten.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Schwindel","Übelkeit","Erbrechen","Gelenkschmerzen (Arthralgie)"],"haeufig":["QT-Verlängerung im EKG","Durchfall","Erhöhte Leberwerte (Transaminasen)","Muskelschmerzen (Myalgie)"]},"schwangerschaft":"Nur begrenzte Erfahrungen; Anwendung vermeiden, ausser der Nutzen überwiegt das Risiko.","stillzeit":"Bedaquilin reichert sich in der Muttermilch an; während der Behandlung nicht stillen.","hinweise":["Mit einer Mahlzeit einnehmen – dadurch wird etwa doppelt so viel Wirkstoff aufgenommen.","Regelmässige EKG- und Leberwertkontrollen; Herzklopfen oder Ohnmacht sofort melden.","Auf Alkohol verzichten."],"darreichung":["Tabletten"]},"belantamab-mafodotin":{"wirkmechanismus":"Bringt ein Zellgift gezielt in Myelomzellen. Belantamab Mafodotin besteht aus einem humanisierten Antikörper gegen BCMA (B-Zell-Reifungsantigen), das auf Myelomzellen reichlich vorkommt, und dem daran gekoppelten Zellgift Monomethylauristatin F (MMAF). Nach der Aufnahme in die Zelle stört MMAF die Mikrotubuli, stoppt die Zellteilung und löst den Zelltod aus; zusätzlich lockt der Antikörper Immunzellen an (ADCC).","nebenwirkungen":{"sehrHaeufig":["Keratopathie (Hornhautveränderungen) mit verschwommenem Sehen und verminderter Sehschärfe","Trockene, gereizte Augen, Fremdkörpergefühl, Lichtempfindlichkeit","Thrombozytopenie (Mangel an Blutplättchen)","Neutropenie, Anämie","Infektionen der Atemwege, inkl. Lungenentzündung","Durchfall","Müdigkeit"],"haeufig":["Infusionsbedingte Reaktionen"],"unbekannt":["Hornhautgeschwür (ulzerative Keratitis)","Pneumonitis (Lungenentzündung durch das Medikament)"]},"schwangerschaft":"Kann das Ungeborene schädigen (enthält ein Zellgift); in der Schwangerschaft nicht anwenden. Zuverlässige Verhütung während und mehrere Monate nach der Behandlung; bei Kombination mit Pomalidomid gilt dessen Schwangerschaftsverhütungsprogramm.","stillzeit":"Während der Behandlung und einige Monate danach nicht stillen.","hinweise":["Vor jeder Dosis augenärztliche Untersuchung; konservierungsmittelfreie Tränenersatzmittel mehrmals täglich anwenden.","Bei verschwommenem Sehen kein Fahrzeug lenken und keine Maschinen bedienen.","Blutungszeichen (Nasenbluten, blaue Flecken, schwarzer Stuhl) sofort melden."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"belatacept":{"wirkmechanismus":"Verhindert, dass T-Zellen das transplantierte Organ angreifen. Belatacept ist ein Fusionsprotein aus einem veränderten CTLA-4-Anteil und einem Fc-Fragment von IgG1; es bindet stärker als Abatacept an CD80 und CD86 auf antigenpräsentierenden Zellen. Damit blockiert es das kostimulatorische Signal über CD28, das T-Zellen zur Aktivierung brauchen. Anders als Calcineurin-Hemmer schädigt es die Niere nicht.","nebenwirkungen":{"sehrHaeufig":["Harnwegsinfektionen, Atemwegsinfektionen, CMV-Infektion, Bronchitis","Anämie (Blutarmut), Leukopenie","Elektrolytstörungen (Kalium zu tief oder zu hoch, Phosphat zu tief)","Schlaflosigkeit","Kopfschmerzen","Bluthochdruck oder Blutdruckabfall","Durchfall, Verstopfung, Übelkeit, Erbrechen, Bauchschmerzen","Periphere Ödeme, Fieber, Eiweiss im Urin, erhöhtes Kreatinin"],"gelegentlich":["Lymphoproliferative Erkrankung nach Transplantation (PTLD)"],"unbekannt":["Sepsis, Gürtelrose, BK-Virus-Infektion","Hautkrebs (Plattenepithel- und Basalzellkarzinom)","Progressive multifokale Leukenzephalopathie (PML, schwere Hirninfektion)","Thrombozytopenie, Neutropenie","Erhöhter Blutzucker, Diabetes"]},"schwangerschaft":"Nicht anwenden, ausser wenn eindeutig erforderlich; Frauen im gebärfähigen Alter sollen während und bis 8 Wochen nach der letzten Dosis verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Wird als Infusion in der Transplantationsambulanz gegeben, anfangs häufiger, später alle 4 Wochen – Termine genau einhalten.","Neue Verwirrtheit, Gedächtnis-, Seh- oder Gangstörungen sofort melden.","Sonnenschutz und regelmässige Hautkontrollen."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"belimumab":{"wirkmechanismus":"Bremst B-Lymphozyten, die beim Lupus schädliche Autoantikörper bilden. Belimumab ist ein humaner monoklonaler IgG1-Antikörper, der den löslichen B-Lymphozyten-Stimulator (BLyS, auch BAFF genannt) bindet und dessen Andocken an die Rezeptoren der B-Zellen verhindert. Ohne dieses Überlebenssignal gehen vor allem autoreaktive B-Zellen vermehrt zugrunde und reifen seltener zu antikörperbildenden Plasmazellen heran. Dadurch sinken Autoantikörper wie Anti-dsDNA und die Krankheitsaktivität.","nebenwirkungen":{"sehrHaeufig":["Bakterielle Infektionen (z. B. Bronchitis, Harnwegsinfekt)","Durchfall","Übelkeit"],"haeufig":["Virale Infekte der oberen Atemwege, Rachenentzündung, Magen-Darm-Grippe","Leukopenie (Mangel an weissen Blutkörperchen)","Überempfindlichkeitsreaktionen","Depression","Schlaflosigkeit","Migräne","Gliederschmerzen","Infusions- bzw. Injektionsreaktionen, Fieber"],"gelegentlich":["Anaphylaxie (schwere allergische Reaktion)","Angioödem (Schwellung von Gesicht, Lippen, Rachen)","Nesselsucht, Hautausschlag","Suizidgedanken und suizidales Verhalten"],"selten":["Verzögerte, nicht akute Überempfindlichkeitsreaktionen"],"unbekannt":["Progressive multifokale Leukoenzephalopathie (PML)"]},"schwangerschaft":"Nur anwenden, wenn der Nutzen das Risiko klar überwiegt. Frauen im gebärfähigen Alter sollen während der Behandlung und mindestens 4 Monate danach zuverlässig verhüten.","stillzeit":"Nicht bekannt, ob Belimumab in die Muttermilch übergeht; über Stillen oder Behandlung ist ärztlich zu entscheiden.","hinweise":["Reaktionen sind auch Stunden nach der Infusion möglich: Atemnot, Schwellungen oder Ausschlag sofort melden.","Neu auftretende oder zunehmende Niedergeschlagenheit oder Suizidgedanken sofort ärztlich besprechen.","Impfstatus vor Beginn überprüfen; keine Lebendimpfungen in den 30 Tagen vor und während der Behandlung."],"darreichung":["Pulver zur Herstellung eines Infusionslösungskonzentrats","Injektionslösung im Fertigpen","Injektionslösung in Fertigspritze"]},"belzutifan":{"wirkmechanismus":"Blockiert ein Eiweiss, das Tumoren zum Wachsen und zur Bildung neuer Blutgefässe anregt. Belzutifan hemmt den Transkriptionsfaktor HIF-2-alpha (Hypoxie-induzierbarer Faktor 2 alpha), indem es dessen Verbindung mit HIF-1-beta verhindert. Bei der Von-Hippel-Lindau-Krankheit und den meisten klarzelligen Nierenzellkarzinomen wird HIF-2-alpha nicht abgebaut und treibt das Tumorwachstum an. Die Hemmung senkt die Bildung von Wachstums- und Gefässfaktoren (z. B. VEGF), aber auch von Erythropoetin – das erklärt die häufige Blutarmut.","nebenwirkungen":{"sehrHaeufig":["Anämie (Blutarmut)","Müdigkeit","Kopfschmerzen, Schwindel","Übelkeit","Atemnot"],"haeufig":["Hypoxie (Sauerstoffmangel im Blut)"]},"schwangerschaft":"Nicht anwenden (kann das ungeborene Kind schädigen). Frauen müssen während und bis 1 Woche nach der letzten Dosis zuverlässig nichthormonal verhüten; Männer mit Partnerin im gebärfähigen Alter ebenfalls verhüten.","stillzeit":"Während der Behandlung und bis 1 Woche nach der letzten Dosis nicht stillen.","hinweise":["Hämoglobin und Sauerstoffsättigung werden regelmässig kontrolliert.","Atemnot, starke Müdigkeit oder Schwindel ärztlich melden.","Hormonale Verhütungsmittel können unwirksam sein – Verhütung mit der Ärztin oder dem Arzt besprechen."],"darreichung":["Filmtabletten"]},"bempedoinsaeure":{"wirkmechanismus":"Senkt das LDL-Cholesterin, indem es die Cholesterinbildung in der Leber bremst. Bempedoinsäure ist ein Prodrug, das erst in der Leber durch das Enzym ACSVL1 zu Bempedoyl-CoA aktiviert wird. Dieses hemmt die ATP-Citrat-Lyase, ein Enzym der Cholesterinsynthese, das vor der HMG-CoA-Reduktase (dem Angriffspunkt der Statine) liegt. Die Leber bildet daraufhin mehr LDL-Rezeptoren und nimmt mehr LDL aus dem Blut auf. Weil das aktivierende Enzym in der Skelettmuskulatur fehlt, wirkt der Stoff dort kaum.","nebenwirkungen":{"haeufig":["Anämie (Blutarmut)","Hyperurikämie (erhöhte Harnsäure), Gicht","Schmerzen in Armen oder Beinen","Erhöhte Leberwerte (AST)"],"gelegentlich":["Erniedrigtes Hämoglobin","Erhöhte Leberwerte (ALT)","Erhöhte Nierenwerte (Kreatinin, Harnstoff), verminderte Nierenfunktion"]},"schwangerschaft":"Kontraindiziert, da die Hemmung der Cholesterinbildung dem ungeborenen Kind schaden kann; Frauen im gebärfähigen Alter müssen zuverlässig verhüten.","stillzeit":"Kontraindiziert, da ein Übergang in die Muttermilch und ein Risiko für das Kind nicht ausgeschlossen werden können.","hinweise":["Kann unabhängig von den Mahlzeiten eingenommen werden.","Gelenkschmerzen mit Schwellung oder Rötung (Gicht) ärztlich melden; Harnsäure kontrollieren lassen.","Bei Kombination mit Simvastatin höchstens 40 mg Simvastatin pro Tag.","Nustendi enthält zusätzlich Ezetimib (Kombinationspräparat)."],"darreichung":["Filmtabletten"]},"benazepril":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Bildung des gefässverengenden Hormons Angiotensin II hemmt. Benazepril ist ein Prodrug, das in der Leber zum wirksamen Benazeprilat umgewandelt wird; dieses hemmt das Angiotensin-Converting-Enzym (ACE). Dadurch sinken Angiotensin II und Aldosteron, die Gefässe erweitern sich und die Salz- und Wasserausscheidung nimmt zu. Weil ACE auch Bradykinin abbaut, steigt dieses an – das erklärt Reizhusten und Angioödeme.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel","Herzklopfen","Blutdruckabfall beim Aufstehen (orthostatische Beschwerden)","Flush (Hautrötung mit Wärmegefühl)","Husten, Beschwerden der oberen Atemwege","Magen-Darm-Beschwerden (Übelkeit, Bauchschmerzen, Durchfall, Verstopfung)","Hautausschlag, Juckreiz, Lichtempfindlichkeit","Häufiges Wasserlassen, Müdigkeit"],"selten":["Angina pectoris (Brustenge), Herzrhythmusstörungen","Kribbeln, Schlafstörungen, Nervosität","Angioödem (Schwellung von Gesicht, Lippen, Zunge oder Rachen)","Pemphigus (blasenbildende Hauterkrankung)","Gelenk- und Muskelschmerzen","Anstieg von Kreatinin und Harnstoff","Hepatitis, Gelbsucht durch Gallenstau"],"sehrSelten":["Hämolytische Anämie, Thrombozytopenie","Neutropenie bis Agranulozytose","Tinnitus (Ohrensausen), Geschmacksstörungen","Pankreatitis","Stevens-Johnson-Syndrom","Nierenfunktionsstörung bis Nierenversagen","Herzinfarkt"],"unbekannt":["Hyperkaliämie (erhöhtes Kalium)","Intestinales Angioödem (Darmschwellung mit Bauchschmerzen)","Anaphylaktoide Reaktionen"]},"schwangerschaft":"Im 1. Drittel nicht empfohlen, im 2. und 3. Drittel kontraindiziert (Schädigung der kindlichen Nieren, Fruchtwassermangel, Verknöcherungsstörungen des Schädels). Bei Kinderwunsch oder Schwangerschaft auf ein anderes Mittel umstellen.","stillzeit":"Geht in sehr geringer Menge in die Muttermilch über. Bei Frühgeborenen und in den ersten Lebenswochen nicht empfohlen; bei älteren Säuglingen nach ärztlicher Abwägung möglich.","hinweise":["Bei Schwellungen von Gesicht, Lippen, Zunge oder Rachen oder bei Atemnot sofort den Notfall aufsuchen (Angioödem).","Trockener Reizhusten ist eine typische Nebenwirkung – ärztlich melden, nicht selbst absetzen.","Kalium und Nierenwerte regelmässig kontrollieren; kaliumhaltige Salzersatzmittel meiden.","Zu Beginn sind Schwindel und Benommenheit möglich – Vorsicht beim Autofahren."],"darreichung":["Filmtabletten"]},"bendamustin":{"wirkmechanismus":"Hemmt die Vermehrung von Krebszellen, indem es ihr Erbgut schädigt. Bendamustin verbindet eine Stickstofflost-Gruppe mit einem Benzimidazolring und wirkt als bifunktionelles Alkylans: Es vernetzt DNA-Stränge und löst den Zelltod aus, teilweise auch bei Resistenz gegen andere Alkylanzien. Es wird überwiegend durch Hydrolyse abgebaut; über CYP1A2 entstehen geringe Mengen aktiver Metaboliten.","nebenwirkungen":{"sehrHaeufig":["Infektionen","Leukopenie, Thrombozytopenie (Mangel an weissen Blutkörperchen bzw. Blutplättchen), Hämoglobin-Abfall","Übelkeit, Erbrechen","Schleimhautentzündung","Müdigkeit, Fieber","Anstieg von Kreatinin und Harnstoff"],"haeufig":["Neutropenie, Anämie, Blutungen","Allergische Reaktionen und Infusionsreaktionen","Tumorlysesyndrom","Herzrhythmusstörungen, Herzklopfen, Angina pectoris","Durchfall, Verstopfung, Mundentzündung","Haarausfall, Hautveränderungen","Hypokaliämie (Kaliummangel), erhöhte Leberwerte","Schlaflosigkeit, Schwindel"],"gelegentlich":["Perikarderguss, Vorhofflimmern","Myelodysplastisches Syndrom, akute myeloische Leukämie"],"selten":["Sepsis (Blutvergiftung)","Anaphylaxie (schwere allergische Reaktion)","Schläfrigkeit, Stimmverlust","Kreislaufversagen","Hautrötung, Juckreiz, Ausschlag"],"sehrSelten":["Hämolyse (Blutzerfall)","Herzinfarkt, Herzschwäche","Lungenfibrose, atypische Lungenentzündung","Periphere Neuropathie (Nervenschäden)","Magen-Darm-Blutung","Multiorganversagen"],"unbekannt":["Leberversagen, Hepatitis-B-Reaktivierung","Nierenversagen","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS (schwere Hautreaktionen)","Progressive multifokale Leukoenzephalopathie (PML)","Pneumonitis"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Notwendigkeit: Bendamustin kann das ungeborene Kind schädigen. Frauen müssen während der Behandlung sicher verhüten; Männer sollen bis 6 Monate danach kein Kind zeugen.","stillzeit":"Kontraindiziert – nicht stillen.","hinweise":["Vor jedem Zyklus Blutbildkontrolle; bei Fieber, Infektzeichen oder Hautausschlag sofort ärztliche Hilfe holen.","Keine Lebendimpfungen, insbesondere keine Gelbfieberimpfung.","Müdigkeit und Schwindel möglich – Vorsicht beim Autofahren.","Haut regelmässig kontrollieren lassen und vor Sonne schützen (heller Hautkrebs)."],"darreichung":["Pulver zur Herstellung eines Konzentrats für eine Infusionslösung"]},"benfotiamin":{"wirkmechanismus":"Liefert Vitamin B1 (Thiamin), das der Körper für die Energiegewinnung aus Kohlenhydraten und für die Funktion der Nerven braucht. Benfotiamin ist eine fettlösliche Vorstufe: Im Darm entsteht daraus S-Benzoylthiamin, das besser aufgenommen wird als wasserlösliche Thiaminsalze und im Körper zu Thiamin umgewandelt wird. Dessen aktive Form Thiaminpyrophosphat ist Coenzym wichtiger Enzyme des Zuckerstoffwechsels (Pyruvatdehydrogenase, Alpha-Ketoglutaratdehydrogenase, Transketolase).","nebenwirkungen":{"sehrSelten":["Überempfindlichkeitsreaktionen (Hautausschlag, Nesselsucht)"],"unbekannt":["Magen-Darm-Beschwerden wie Übelkeit"]},"schwangerschaft":"Der Tagesbedarf an Vitamin B1 ist in der Schwangerschaft erhöht und soll gedeckt werden. Höhere Dosen nur bei nachgewiesenem Mangel und nach ärztlicher Abwägung, da Daten fehlen.","stillzeit":"Thiamin geht in die Muttermilch über; höhere Dosen nur bei nachgewiesenem Mangel und nach ärztlicher Abwägung.","hinweise":["Unzerkaut mit etwas Flüssigkeit einnehmen.","Alkohol und grosse Mengen schwarzer Tee vermindern die Aufnahme von Vitamin B1.","Anhaltende Missempfindungen oder Taubheit in Händen und Füssen ärztlich abklären lassen – nicht jede Nervenschädigung beruht auf einem Vitamin-B1-Mangel."],"darreichung":["Tabletten"]},"benralizumab":{"wirkmechanismus":"Beseitigt eosinophile Granulozyten, die bei bestimmten Asthmaformen die Entzündung antreiben. Benralizumab bindet an die Alpha-Untereinheit des Interleukin-5-Rezeptors auf Eosinophilen und Basophilen. Weil dem Antikörper ein bestimmter Zuckerrest (Fucose) fehlt, bindet er besonders stark an natürliche Killerzellen, die die markierten Zellen gezielt abtöten (antikörperabhängige zelluläre Zytotoxizität). Die Eosinophilen im Blut sinken innert 24 Stunden fast vollständig.","nebenwirkungen":{"haeufig":["Rachenentzündung (Pharyngitis)","Überempfindlichkeitsreaktionen (Nesselsucht, Ausschlag)","Kopfschmerzen","Fieber","Reaktionen an der Einstichstelle (Schmerz, Rötung, Juckreiz)"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Begrenzte Erfahrungen; Antikörper gehen über die Plazenta auf das Kind über. Vorzugsweise nicht anwenden, ausser der Nutzen für die Mutter überwiegt das mögliche Risiko für das Kind.","stillzeit":"Nicht bekannt, ob Benralizumab in die Muttermilch übergeht; Anwendung nach ärztlicher Abwägung.","hinweise":["Die ersten drei Injektionen im Abstand von 4 Wochen, danach alle 8 Wochen unter die Haut; nach Schulung ist die Selbstinjektion mit dem Fertigpen möglich.","Im Kühlschrank lagern, nicht einfrieren.","Bei Atemnot, Ausschlag oder Schwellungen nach der Injektion sofort ärztliche Hilfe holen.","Asthma- und Kortisonmedikamente nicht eigenmächtig absetzen."],"darreichung":["Injektionslösung (Fertigpen, Fertigspritze)"]},"benzoylperoxid":{"wirkmechanismus":"Wirkt gegen die an der Akne beteiligten Bakterien und löst verhornte Hautschüppchen. Benzoylperoxid zerfällt in der Haut zu Benzoesäure und setzt dabei reaktiven Sauerstoff frei, der Cutibacterium acnes (früher Propionibacterium acnes) abtötet – Resistenzen entstehen dabei nicht, weshalb es mit Antibiotika zum Auftragen kombiniert wird. Zusätzlich wirkt es schälend (keratolytisch) und mitesserlösend (komedolytisch) und vermindert freie Fettsäuren im Talg.","nebenwirkungen":{"sehrHaeufig":["Brennen der Haut","Rötung (Erythem)","Schuppung (Hautabschälung)","Trockene Haut"],"haeufig":["Juckreiz","Hautschmerzen, Stechen","Hautreizung (irritative Kontaktdermatitis)"],"gelegentlich":["Allergische Kontaktdermatitis"],"unbekannt":["Schwellung des Gesichts","Schwere allergische Reaktionen (Anaphylaxie) mit Engegefühl im Hals, Atemnot oder Kreislaufschwäche"]},"schwangerschaft":"Benzoylperoxid allein kann nach ärztlicher Abwägung angewendet werden, da nur wenig in den Körper gelangt. Die Kombination mit Adapalen (Epiduo) ist in der Schwangerschaft kontraindiziert.","stillzeit":"Kann angewendet werden; nicht auf die Brust auftragen, damit der Säugling nicht damit in Kontakt kommt.","hinweise":["Bleicht Haare, Augenbrauen, Kleidung, Handtücher und Bettwäsche – Kontakt vermeiden und nach dem Auftragen die Hände waschen.","Mit niedriger Konzentration oder seltener Anwendung beginnen; anfängliche Rötung und Schuppung lassen meist nach.","Sonnenschutz verwenden; nicht auf verletzte Haut auftragen."],"darreichung":["Gel"]},"benzydamin":{"wirkmechanismus":"Lindert Schmerzen und Entzündung direkt an der Schleimhaut von Mund und Rachen. Benzydamin ist ein Indazol-Abkömmling, der im Gegensatz zu klassischen NSAR die Prostaglandinbildung nur schwach hemmt. Es vermindert die Bildung entzündungsfördernder Botenstoffe wie Tumornekrosefaktor-alpha und Interleukin-1-beta und stabilisiert Zellmembranen; dadurch wirkt es zusätzlich leicht örtlich betäubend. Bei Anwendung im Mund gelangt nur wenig Wirkstoff ins Blut.","nebenwirkungen":{"gelegentlich":["Lichtempfindlichkeit der Haut (Photosensibilität)"],"selten":["Brennen im Mund","Mundtrockenheit","Überempfindlichkeitsreaktionen (Hautausschlag, Juckreiz)"],"sehrSelten":["Laryngospasmus (Verkrampfung des Kehlkopfs)","Angioödem (Schwellung von Gesicht, Lippen oder Rachen)"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Taubheitsgefühl im Mund (orale Hypästhesie)"]},"schwangerschaft":"Erfahrungen fehlen; in der Schwangerschaft nur nach ärztlicher Rücksprache anwenden.","stillzeit":"Erfahrungen fehlen; in der Stillzeit nur nach ärztlicher Rücksprache anwenden.","hinweise":["Lösung nach dem Gurgeln oder Spülen ausspucken, nicht schlucken.","Lutschtabletten langsam im Mund zergehen lassen, nicht kauen oder schlucken.","Ohne ärztlichen Rat nicht länger als 7 Tage anwenden."],"darreichung":["Lösung zum Gurgeln und Spülen","Rachenspray","Lutschtabletten"]},"benzylbenzoat":{"wirkmechanismus":"Tötet Krätzmilben und ihre Eier auf der Haut ab. Benzylbenzoat wirkt als Nervengift auf die Milben; der genaue Mechanismus ist nicht vollständig geklärt. Es wird nur in geringem Mass durch die Haut aufgenommen und im Körper rasch zu Benzoesäure und Hippursäure abgebaut, die über die Nieren ausgeschieden werden.","nebenwirkungen":{"unbekannt":["Brennen, Hautreizung und Juckreiz nach dem Auftragen","Allergische Kontaktdermatitis (Hautausschlag)","Augenreizung bei Kontakt mit den Augen"]},"schwangerschaft":"Erfahrungen begrenzt; nur nach ärztlicher Abwägung anwenden.","stillzeit":"Nur nach ärztlicher Abwägung; nicht im Brustbereich auftragen bzw. vor dem Stillen gründlich abwaschen.","hinweise":["Auf die saubere, trockene Haut des ganzen Körpers vom Hals abwärts auftragen; Einwirkzeit und Wiederholung gemäss Packungsbeilage.","Kontaktpersonen gleichzeitig mitbehandeln; Kleidung, Handtücher und Bettwäsche bei mindestens 60 °C waschen.","Der Juckreiz kann nach erfolgreicher Behandlung noch 2–4 Wochen anhalten."],"darreichung":["Emulsion zur Anwendung auf der Haut"]},"benzylpenicillin":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand verhindert. Benzylpenicillin blockiert die Penicillin-bindenden Proteine (Transpeptidasen) und damit die Quervernetzung des Peptidoglykans; sich teilende Bakterien gehen zugrunde (bakterizide Wirkung). Es wirkt sehr stark gegen Streptokokken, Pneumokokken, Meningokokken, Treponemen (Syphilis-Erreger), Clostridien und Borrelien, wird aber von Beta-Laktamasen, etwa der meisten Staphylokokken, zerstört. Da es von der Magensäure abgebaut wird, muss es gespritzt werden; die Ausscheidung erfolgt rasch über die Niere.","nebenwirkungen":{"haeufig":["Allergische Hautreaktionen (Ausschlag, Nesselsucht, Juckreiz)"],"selten":["Anaphylaxie (schwere allergische Reaktion bis zum Kreislaufschock)","Angioödem (Schwellung von Gesicht und Rachen)"],"sehrSelten":["Hämolytische Anämie (Blutzerfall)","Interstitielle Nephritis (Nierenentzündung)","Pseudomembranöse Kolitis (schwere Darmentzündung)"],"unbekannt":["Krampfanfälle, Muskelzuckungen, Verwirrtheit bei sehr hohen Dosen oder eingeschränkter Nierenfunktion","Blutbildveränderungen (Neutropenie, Thrombozytopenie, Eosinophilie)","Elektrolytstörungen (zu viel Natrium oder Kalium) bei hohen Dosen","Jarisch-Herxheimer-Reaktion bei Syphilis oder Borreliose","Venenreizung (Phlebitis) an der Infusionsstelle","Übelkeit, Durchfall, Entzündung von Mundschleimhaut oder Zunge","Arzneimittelfieber, Serumkrankheit"]},"schwangerschaft":"Erlaubt, wenn eine Behandlung nötig ist; lange Erfahrung ohne Hinweise auf eine Schädigung des Kindes (z. B. Mittel der Wahl bei Syphilis in der Schwangerschaft).","stillzeit":"Erlaubt; nur geringe Mengen gehen in die Muttermilch über (beim Säugling Durchfall oder Sensibilisierung möglich).","hinweise":["Wird im Spital oder in der Praxis als Injektion oder Infusion gegeben.","Eine frühere Penicillinallergie unbedingt vorher melden; nach der Gabe auf Ausschlag, Atemnot oder Schwindel achten.","Fieber und Schüttelfrost wenige Stunden nach Beginn einer Syphilisbehandlung sind meist eine harmlose Jarisch-Herxheimer-Reaktion – trotzdem ärztlich melden."],"darreichung":["Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"berotralstat":{"wirkmechanismus":"Verhindert die übermässige Bildung von Bradykinin, das beim erblichen Angioödem die Schwellungen auslöst. Berotralstat ist ein kleines Molekül, das eingenommen wird und das Enzym Plasmakallikrein hemmt. Damit wird die Spaltung von hochmolekularem Kininogen zu Bradykinin gebremst, und die Attacken werden seltener. Berotralstat ist Substrat von P-Glykoprotein und BCRP und hemmt selbst mässig CYP3A4 und CYP2D6 sowie P-Glykoprotein.","nebenwirkungen":{"sehrHaeufig":["Bauchschmerzen","Durchfall","Kopfschmerzen"],"haeufig":["Erbrechen","Sodbrennen (gastroösophagealer Reflux)","Blähungen","Hautausschlag","Erhöhte Leberwerte (ALT, AST)"]},"schwangerschaft":"Keine ausreichenden Daten; vorsichtshalber während der Schwangerschaft nicht anwenden.","stillzeit":"Nicht bekannt, ob Berotralstat in die Muttermilch übergeht (bei Tieren ja); Nutzen und Risiko ärztlich abwägen.","hinweise":["Einmal täglich zu einer Mahlzeit einnehmen.","Für akute Attacken trotzdem immer ein Notfallmedikament mitführen.","Vor jeder neuen Medikation Wechselwirkungen in der Apotheke prüfen lassen."],"darreichung":["Hartkapseln"]},"betahistin":{"wirkmechanismus":"Soll bei Menière-Krankheit die Häufigkeit und Stärke der Schwindelanfälle vermindern. Betahistin ist ein Histamin-Analogon: schwacher Agonist an H1-Rezeptoren und starker Antagonist an H3-Rezeptoren. Es verbessert vermutlich die Durchblutung im Innenohr und dämpft die Aktivität der Gleichgewichtskerne im Hirnstamm. Es wird rasch durch Monoaminoxidasen zum unwirksamen Abbauprodukt 2-Pyridylessigsäure abgebaut.","nebenwirkungen":{"haeufig":["Übelkeit","Dyspepsie (Verdauungsbeschwerden)","Kopfschmerzen"],"unbekannt":["Überempfindlichkeitsreaktionen bis zur Anaphylaxie","Leichte Magenbeschwerden (Erbrechen, Bauchschmerzen, Blähungen)","Hautreaktionen (Angioödem, Nesselsucht, Ausschlag, Juckreiz)"]},"schwangerschaft":"Keine ausreichenden Daten; nur anwenden, wenn eindeutig erforderlich.","stillzeit":"Nicht bekannt, ob Betahistin in die Muttermilch übergeht; nur nach ärztlicher Abwägung.","hinweise":["Mit dem Essen einnehmen (bessere Magenverträglichkeit).","Die Wirkung kann sich erst nach einigen Wochen zeigen."],"darreichung":["Tabletten"]},"betain":{"wirkmechanismus":"Senkt den Spiegel der schädlichen Aminosäure Homocystein im Blut. Betain liefert eine Methylgruppe, mit der das Enzym Betain-Homocystein-Methyltransferase in Leber und Niere Homocystein zu Methionin umbaut (Remethylierung). Dieser Weg umgeht den gestörten Abbau beziehungsweise die gestörte folat- und Vitamin-B12-abhängige Remethylierung. Bei Cystathionin-beta-Synthase-Mangel steigt dadurch das Methionin im Blut an.","nebenwirkungen":{"sehrHaeufig":["Erhöhter Methioninspiegel im Blut"],"gelegentlich":["Hirnödem (Hirnschwellung)","Appetitlosigkeit","Unruhe, Reizbarkeit","Durchfall, Übelkeit, Erbrechen, Magenbeschwerden, Zungenentzündung","Haarausfall, Nesselsucht, ungewöhnlicher Hautgeruch","Harninkontinenz"]},"schwangerschaft":"Nur wenige Daten. Anwendung nur, wenn eindeutig nötig, mit engmaschiger Kontrolle von Methionin und Homocystein.","stillzeit":"Nicht bekannt, ob Betain vermehrt in die Muttermilch übergeht. Anwendung nur nach ärztlicher Abwägung.","hinweise":["Pulver mit dem beigelegten Messlöffel abmessen, in Wasser, Saft, Milch oder Säuglingsnahrung auflösen oder unter das Essen mischen und sofort einnehmen.","Diät und ergänzende Vitamine (B6, B12, Folsäure) wie verordnet weiterführen.","Methionin- und Homocysteinspiegel regelmässig kontrollieren lassen.","Flasche nach Gebrauch gut verschliessen (Pulver zieht Feuchtigkeit an)."],"darreichung":["Pulver zum Einnehmen"]},"betamethason":{"wirkmechanismus":"Hemmt Entzündungen, allergische Reaktionen und überschiessende Immunreaktionen stark. Betamethason ist ein synthetisches Glukokortikoid, etwa 25- bis 30-mal stärker entzündungshemmend als Cortisol und praktisch ohne salzbindende Wirkung. Über den Glukokortikoid-Rezeptor im Zellinneren unterdrückt es die Bildung von Entzündungsbotenstoffen (z. B. Prostaglandine, Zytokine) und die Aktivität von Immunzellen. Als Valerat oder Dipropionat wirkt es auf der Haut stark (Klasse III); in Depotspritzen sorgt ein schwer lösliches Ester für eine Wirkung über mehrere Wochen.","nebenwirkungen":{"haeufig":["Juckreiz, Brennen oder Schmerzen an der Auftragsstelle (Haut)"],"sehrSelten":["Hautverdünnung (Atrophie), Dehnungsstreifen, erweiterte Äderchen, Pigmentveränderungen, vermehrte Behaarung (äusserliche Anwendung)","Allergische Kontaktdermatitis, Verschlechterung der Hauterkrankung, pustulöse Psoriasis (äusserliche Anwendung)","Bei grossflächiger oder langer Anwendung auf der Haut: Unterdrückung der Nebennieren, Cushing-Zeichen, Wachstumsverzögerung bei Kindern"],"unbekannt":["Cushing-Syndrom, Unterdrückung der Nebennierenfunktion, Zyklusstörungen (Tabletten, Injektion)","Erhöhter Blutzucker, Wassereinlagerungen, Bluthochdruck, Kaliummangel","Osteoporose, Muskelschwäche, Knochennekrose, Magen-Darm-Geschwüre","Erhöhte Infektanfälligkeit, Verschleierung von Infektionszeichen","Psychische Veränderungen: Schlafstörungen, Euphorie, Depression, Psychose","Grauer oder grüner Star, verschwommenes Sehen","Hautverdünnung und helle Flecken an der Einstichstelle; vorübergehende Gelenkreizung nach Gelenkinjektion","Anaphylaktische Reaktionen (Injektion)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung; bei langer, hoch dosierter Anwendung sind Wachstumsverzögerung des Kindes und eine Nebennierenunterfunktion beim Neugeborenen möglich. Bei drohender Frühgeburt wird Betamethason gezielt zur Förderung der kindlichen Lungenreife eingesetzt. Auf der Haut nur kleinflächig und kurz.","stillzeit":"Geht in geringen Mengen in die Muttermilch über: kurzfristige oder äusserliche Anwendung nach Abwägung möglich, nicht auf die Brust auftragen; bei hohen Dosen über längere Zeit ärztliche Abwägung.","hinweise":["Stark wirksame Kortisoncremes (Klasse III) nicht ohne ärztliche Anweisung im Gesicht, in Hautfalten, im Genitalbereich oder unter luftdichten Verbänden anwenden.","Nach längerer Einnahme nicht abrupt absetzen, sondern schrittweise ausschleichen.","Bei Diabetes nach einer Depotspritze den Blutzucker häufiger kontrollieren.","HIV-Medikamente mit Ritonavir oder Cobicistat dem Arzt vor einer Kortisonbehandlung angeben."],"darreichung":["Tabletten","Depot-Injektionssuspension","Creme","Salbe","Lösung und Lotion zur Anwendung auf Haut und Kopfhaut"]},"bethanechol":{"wirkmechanismus":"Regt die Blasenmuskulatur zur Entleerung an. Bethanechol ist ein synthetischer Cholinester, der Muskarinrezeptoren direkt aktiviert (direktes Parasympathomimetikum); da es von Cholinesterasen nicht abgebaut wird, wirkt es länger als Acetylcholin. Es steigert die Spannung des Blasenmuskels (Detrusor) und die Bewegungen des Magen-Darm-Trakts, bei nur geringer Wirkung auf Nikotinrezeptoren. Als quaternäre Verbindung gelangt es kaum ins Gehirn.","nebenwirkungen":{"unbekannt":["Bauchkrämpfe, Übelkeit, Durchfall, Aufstossen","Vermehrter Speichelfluss und Schwitzen, Hautrötung (Flush)","Häufiger Harndrang","Blutdruckabfall, langsamer Puls","Bronchospasmus (Verkrampfung der Atemwege)","Tränenfluss, Sehstörungen durch Pupillenverengung","Kopfschmerzen"]},"schwangerschaft":"Sicherheit nicht belegt; nur nach strenger ärztlicher Abwägung.","stillzeit":"Keine ausreichenden Daten; Anwendung nicht empfohlen.","hinweise":["Auf nüchternen Magen einnehmen (etwa 1 Stunde vor oder 2 Stunden nach dem Essen), um Übelkeit und Erbrechen zu vermeiden.","Langsam aufstehen: Schwindel durch Blutdruckabfall möglich."],"darreichung":["Tabletten"]},"bevacizumab":{"wirkmechanismus":"Hungert den Tumor aus, indem es die Bildung neuer Blutgefässe bremst. Bevacizumab ist ein humanisierter monoklonaler Antikörper, der den Wachstumsfaktor VEGF (vaskulärer endothelialer Wachstumsfaktor) bindet. VEGF kann dadurch nicht mehr an seine Rezeptoren auf Gefässzellen andocken. Die Tumorgefässe bilden sich zurück und neue entstehen kaum, was das Tumorwachstum verlangsamt.","nebenwirkungen":{"sehrHaeufig":["Hypertonie (Bluthochdruck)","Blutungen, vor allem Nasenbluten","Proteinurie (Eiweiss im Urin)","Neutropenie (Mangel an weissen Blutkörperchen, auch mit Fieber) in Kombination mit Chemotherapie","Durchfall, Übelkeit, Bauchschmerzen","Kopfschmerzen, Geschmacksstörungen, Müdigkeit","Wundheilungsstörungen","Ovarialinsuffizienz (Ausbleiben der Eierstockfunktion)"],"haeufig":["Magen-Darm-Perforation (Durchbruch)","Fisteln und Abszesse","Arterielle Thromboembolien (z. B. Herzinfarkt, Schlaganfall)","Venöse Thrombosen und Lungenembolie","Schwere Blutungen, z. B. Lungenblutung bei Lungenkrebs","Herzinsuffizienz (Herzschwäche)","Sepsis (Blutvergiftung)","Überempfindlichkeits- und Infusionsreaktionen"],"gelegentlich":["Nephrotisches Syndrom (starker Eiweissverlust über die Niere)"],"selten":["Posteriores reversibles Enzephalopathie-Syndrom (PRES: Kopfschmerzen, Sehstörungen, Krampfanfälle)","Nekrotisierende Fasziitis (schwere Weichteilinfektion)"],"sehrSelten":["Hypertensive Enzephalopathie (Hirnschädigung durch sehr hohen Blutdruck)"],"unbekannt":["Kiefernekrose","Durchbruch der Nasenscheidewand","Gallenblasenperforation","Thrombotische Mikroangiopathie","Aneurysmen und Arteriendissektionen (Gefässaussackungen, Einrisse der Gefässwand)","Pulmonale Hypertonie (Lungenhochdruck)"]},"schwangerschaft":"Kontraindiziert, da Fruchtschäden zu erwarten sind. Sichere Verhütung während und bis 6 Monate nach der letzten Dosis.","stillzeit":"Nicht stillen während der Behandlung und bis 6 Monate nach der letzten Dosis.","hinweise":["Blutdruck und Urin werden vor jeder Gabe kontrolliert.","Vor Operationen und Zahneingriffen die Behandlung angeben – ein Abstand von mindestens 4 Wochen ist nötig.","Starke Bauchschmerzen, Bluterbrechen, schwarzer Stuhl, Atemnot oder einseitige Lähmungen sofort ärztlich abklären lassen."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"bexaroten":{"wirkmechanismus":"Bremst das Wachstum bösartiger T-Zellen in der Haut. Bexaroten ist ein Retinoid (mit Vitamin A verwandt), das selektiv an Retinoid-X-Rezeptoren (RXR) bindet. Diese Rezeptoren steuern als Transkriptionsfaktoren Zellwachstum, Ausreifung und programmierten Zelltod (Apoptose); ihre Aktivierung hemmt das Wachstum der Lymphomzellen und fördert deren Absterben.","nebenwirkungen":{"sehrHaeufig":["Hyperlipidämie (erhöhte Blutfette, v. a. Triglyceride und Cholesterin)","Hypothyreose (Schilddrüsenunterfunktion)","Leukopenie (Mangel an weissen Blutkörperchen)","Juckreiz, Hautausschlag, schuppende Hautentzündung","Kopfschmerzen","Schwäche, Schmerzen"],"haeufig":["Anämie (Blutarmut)","Erhöhte Leberwerte","Übelkeit, Durchfall, Erbrechen","Periphere Ödeme (Wassereinlagerungen)","Haarausfall, trockene Haut","Schlaflosigkeit, Schwindel"],"gelegentlich":["Pankreatitis (Bauchspeicheldrüsenentzündung)","Katarakt (Grauer Star)","Neutropenie, Thrombozytopenie"]},"schwangerschaft":"Kontraindiziert – Retinoide sind stark fruchtschädigend. Schwangerschaftstest innerhalb einer Woche vor Beginn und danach monatlich; wirksame Verhütung ab 1 Monat vor bis 1 Monat nach der Behandlung, hormonale Methoden nur zusammen mit einer Barrieremethode. Männer verwenden Kondome bis 1 Monat nach Therapieende.","stillzeit":"Kontraindiziert.","hinweise":["Mit einer Mahlzeit einnehmen; Kapseln ganz schlucken.","Blutfette, Schilddrüsenwerte, Leberwerte und Blutbild regelmässig kontrollieren lassen.","Keine Vitamin-A-Präparate einnehmen, Grapefruit meiden und auf guten Sonnenschutz achten.","Starke Bauchschmerzen (Zeichen einer Pankreatitis) sofort melden."],"darreichung":["Kapseln"]},"bezafibrat":{"wirkmechanismus":"Senkt vor allem die Triglyceride und erhöht das «gute» HDL-Cholesterin. Bezafibrat aktiviert Kernrezeptoren der PPAR-Familie, vor allem PPAR-alpha, in Leber und Muskulatur. Dadurch wird die Lipoproteinlipase aktiviert und der Abbau triglyceridreicher Lipoproteine (VLDL) beschleunigt, während die Leber weniger VLDL bildet. Zudem steigt die Bildung der HDL-Bausteine Apolipoprotein A-I und A-II, und das LDL-Cholesterin sinkt mässig.","nebenwirkungen":{"haeufig":["Appetitlosigkeit","Magen-Darm-Beschwerden (z. B. Übelkeit, Bauchschmerzen, Völlegefühl)"],"gelegentlich":["Überempfindlichkeitsreaktionen","Schwindel, Kopfschmerzen","Cholestase (Gallenstau)","Juckreiz, Nesselsucht, Hautausschlag, Haarausfall","Photosensibilität (Lichtempfindlichkeit)","Muskelschwäche, Muskelschmerzen, Muskelkrämpfe","Akutes Nierenversagen, Anstieg von Kreatinin und Kreatinkinase","Erektionsstörungen"],"selten":["Periphere Neuropathie, Kribbeln","Depression, Schlafstörungen","Pankreatitis"],"sehrSelten":["Panzytopenie, Thrombozytopenie","Anaphylaxie","Rhabdomyolyse (Muskelzerfall)","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme","Interstitielle Lungenerkrankung","Gallensteine"]},"schwangerschaft":"Kontraindiziert.","stillzeit":"Kontraindiziert.","hinweise":["Retardtabletten unzerkaut nach einer Mahlzeit mit Flüssigkeit einnehmen.","Muskelschmerzen, -schwäche oder dunklen Urin sofort melden – besonders wichtig bei Kombination mit einem Statin.","Nierenwerte vor und während der Behandlung kontrollieren; unter Gerinnungshemmern INR engmaschig kontrollieren.","Intensive Sonne und Solarium meiden (Lichtempfindlichkeit möglich)."],"darreichung":["Retardtabletten"]},"bicalutamid":{"wirkmechanismus":"Verhindert, dass männliche Hormone das Wachstum von Prostatakrebszellen anregen. Bicalutamid bindet kompetitiv an den Androgenrezeptor, ohne ihn zu aktivieren, und hemmt so die Wirkung von Testosteron und Dihydrotestosteron. Es wirkt peripher; der Testosteronspiegel kann bei alleiniger Gabe sogar leicht ansteigen. Wirksam ist hauptsächlich das R-Enantiomer, das sehr langsam abgebaut wird.","nebenwirkungen":{"sehrHaeufig":["Hitzewallungen","Gynäkomastie und Brustspannen (v. a. bei 150 mg)","Bauchschmerzen, Verstopfung, Übelkeit","Anämie (Blutarmut)","Blut im Urin","Schwindel","Schwäche, Ödeme"],"haeufig":["Erhöhte Leberwerte","Libidoabnahme, Erektionsstörungen","Depression, Schläfrigkeit","Hautausschlag, Juckreiz, Haarausfall oder vermehrte Behaarung","Appetitlosigkeit, Gewichtszunahme","Herzinsuffizienz, Herzinfarkt"],"gelegentlich":["Überempfindlichkeitsreaktionen, Angioödem, Nesselsucht","Interstitielle Lungenerkrankung"],"selten":["Leberversagen","Photosensibilität (Lichtempfindlichkeit)"],"unbekannt":["QT-Verlängerung"]},"schwangerschaft":"Nicht für Frauen bestimmt (kontraindiziert).","stillzeit":"Nicht für Frauen bestimmt (kontraindiziert).","hinweise":["Täglich zur gleichen Zeit einnehmen.","Leberwerte werden regelmässig kontrolliert; Gelbfärbung, dunkler Urin oder starke Müdigkeit sofort melden.","Bei Schwindel oder Schläfrigkeit nicht Auto fahren."],"darreichung":["Filmtabletten"]},"bictegravir-emtricitabin-tenofoviralafenamid":{"wirkmechanismus":"Hemmt die Vermehrung von HIV an zwei Stellen. Bictegravir blockiert die Integrase und verhindert den Einbau der Virus-DNA in das Erbgut der Wirtszelle (Strangtransfer). Emtricitabin und Tenofovir (aus der Vorstufe Tenofoviralafenamid freigesetzt) werden in den Zellen zu ihren aktiven Formen phosphoryliert, von der Reversen Transkriptase in die Virus-DNA eingebaut und führen zum Kettenabbruch. Bictegravir hemmt zudem Nierentransporter (OCT2, MATE1), was den Kreatininwert leicht erhöht, ohne die Nierenfunktion zu verschlechtern.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel","Durchfall, Übelkeit","Abnorme Träume","Depression","Müdigkeit"],"gelegentlich":["Erbrechen, Bauchschmerzen, Verdauungsbeschwerden, Blähungen","Angst, Schlafstörungen","Suizidgedanken oder Suizidversuch (vor allem bei psychischer Vorerkrankung)","Hautausschlag, Juckreiz, Nesselsucht, Angioödem","Gelenkschmerzen","Anämie","Erhöhtes Bilirubin"],"unbekannt":["Stevens-Johnson-Syndrom (Einzelfälle nach Markteinführung)"]},"schwangerschaft":"In der Schwangerschaft nach Abwägung durch die HIV-Fachperson; die bisherigen Daten zeigen kein erhöhtes Fehlbildungsrisiko, im letzten Drittel sind die Spiegel aber tiefer – Viruslast engmaschig kontrollieren.","stillzeit":"HIV-positive Mütter sollen grundsätzlich nicht stillen (Übertragungsrisiko); ein Stillwunsch ist mit der HIV-Fachperson zu besprechen.","hinweise":["Einmal täglich mit oder ohne Mahlzeit einnehmen; keine Dosis auslassen.","Aluminium- oder magnesiumhaltige Antazida: Biktarvy mindestens 2 Stunden vorher einnehmen. Calcium- und Eisenpräparate nur zusammen mit einer Mahlzeit gleichzeitig einnehmen.","Bei Hepatitis B nicht eigenmächtig absetzen.","Ein leichter Kreatininanstieg zu Beginn ist meist harmlos (Hemmung eines Nierentransporters)."],"darreichung":["Filmtabletten"]},"bifonazol":{"wirkmechanismus":"Hemmt das Wachstum von Hautpilzen, indem es den Aufbau ihrer Zellmembran stört. Bifonazol blockiert die Ergosterol-Bildung der Pilze an zwei Stellen (Lanosterol-14-alpha-Demethylase und HMG-CoA-Reduktase) und wirkt so gegen Fadenpilze, Hefen und Schimmelpilze. Der Wirkstoff bleibt lange in der Haut gespeichert, weshalb meist eine Anwendung pro Tag genügt. Er wirkt auch gegen einige grampositive Bakterien wie den Erreger des Erythrasmas.","nebenwirkungen":{"unbekannt":["Schmerzen, Brennen, Rötung oder Schwellung an der Anwendungsstelle","Juckreiz, Hautausschlag, Nesselsucht","Kontaktdermatitis, Ekzem, Bläschen","Trockene, schuppende oder aufgeweichte Haut"]},"schwangerschaft":"In den ersten drei Monaten vorsichtshalber nicht anwenden; danach nur nach ärztlicher Abwägung.","stillzeit":"Übergang in die Muttermilch beim Menschen nicht bekannt; vorsichtshalber nur nach ärztlicher Rücksprache und nie im Brustbereich anwenden.","hinweise":["Der Wirkstoff wirkt lange in der Haut nach; meist genügt eine Anwendung am Abend.","Behandlung auch nach Abklingen der Beschwerden fortsetzen (je nach Pilzart 2–4 Wochen), sonst droht ein Rückfall.","Füsse nach dem Waschen gut abtrocknen, auch zwischen den Zehen; Socken und Handtücher täglich wechseln.","Nicht in die Augen bringen."],"darreichung":["Creme","Lösung"]},"bilastin":{"wirkmechanismus":"Blockiert die Wirkung von Histamin und lindert so allergische Beschwerden an Nase, Augen und Haut. Bilastin ist ein hochselektiver Antagonist peripherer Histamin-H1-Rezeptoren ohne nennenswerte Bindung an andere Rezeptoren. Weil es vom Transportprotein P-Glykoprotein aus dem Gehirn hinausbefördert wird, macht es nicht müde. Es wird praktisch nicht verstoffwechselt und unverändert über Stuhl und Urin ausgeschieden.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Schläfrigkeit"],"gelegentlich":["Schwindel, Müdigkeit","Appetitsteigerung, Gewichtszunahme","Angst, Schlaflosigkeit","Ohrgeräusche (Tinnitus)","EKG-Veränderungen (QT-Verlängerung, Rechtsschenkelblock, Sinusarrhythmie)","Bauchschmerzen, Übelkeit, Durchfall, Mundtrockenheit, Magenschleimhautentzündung","Juckreiz","Erhöhte Leberwerte"],"unbekannt":["Herzklopfen, Herzrasen","Überempfindlichkeitsreaktionen (Anaphylaxie, Angioödem, Atemnot, Hautausschlag)","Erbrechen"]},"schwangerschaft":"Keine ausreichenden Daten; vorsichtshalber nicht anwenden.","stillzeit":"Nicht bekannt, ob Bilastin in die Muttermilch übergeht; nur nach ärztlicher Abwägung.","hinweise":["Nüchtern einnehmen: eine Stunde vor oder zwei Stunden nach einer Mahlzeit oder einem Fruchtsaft.","Macht in der Regel nicht müde; die eigene Reaktion vor dem Autofahren trotzdem prüfen."],"darreichung":["Tabletten"]},"bimatoprost":{"wirkmechanismus":"Senkt den Augeninnendruck, indem mehr Kammerwasser aus dem Auge abfliesst. Bimatoprost ist ein synthetisches Prostamid, chemisch mit dem Prostaglandin F2α verwandt. Es steigert sowohl den Abfluss über das Trabekelwerk als auch den uveoskleralen Abfluss, ohne die Bildung des Kammerwassers zu beeinflussen.","nebenwirkungen":{"sehrHaeufig":["Rötung der Bindehaut (Bindehauthyperämie)"],"haeufig":["Verstärktes Wimpernwachstum (bei 0,3 mg/ml sehr häufig)","Punktförmige Hornhautentzündung","Augenreizung, Fremdkörpergefühl, Augenjucken, Augenschmerzen","Trockenes Auge","Dunkelfärbung der Haut um das Auge, verstärkte Behaarung","Rötung und Juckreiz der Lider"],"gelegentlich":["Dauerhaft dunklere Färbung der Iris","Verschwommenes Sehen, Augenermüdung","Schwellung von Bindehaut und Lidern","Kopfschmerzen","Übelkeit","Wimpernverlust"],"unbekannt":["Makulaödem (Schwellung der Netzhautmitte)","Einsinken des Augenlids (Vertiefung der Lidfurche)","Asthma, Verschlechterung von Asthma oder COPD, Atemnot","Allergische Reaktionen an Auge und Haut","Blutdruckanstieg"]},"schwangerschaft":"Nur bei klarer Notwendigkeit anwenden; ausreichende Erfahrungen beim Menschen fehlen.","stillzeit":"Ob Bimatoprost in die Muttermilch übergeht, ist nicht bekannt; Anwendung nur nach ärztlicher Abwägung, gegebenenfalls abstillen.","hinweise":["Einmal täglich (meist abends) eintropfen; häufigere Anwendung kann die Drucksenkung abschwächen.","Nach dem Eintropfen die Augen kurz schliessen und überschüssige Flüssigkeit von der Lidhaut abwischen (Haarwuchs und Hautverfärbung möglich).","Kontaktlinsen vor dem Eintropfen herausnehmen und frühestens nach 15 Minuten wieder einsetzen; zu anderen Augentropfen 5 Minuten Abstand halten."],"darreichung":["Augentropfen","Augentropfen ohne Konservierungsmittel (Einzeldosen)"]},"bimatoprost-timolol":{"wirkmechanismus":"Senkt den Augeninnendruck über zwei sich ergänzende Wege. Bimatoprost, ein synthetisches Prostamid (Prostaglandin-Analogon), verbessert den Abfluss des Kammerwassers über das Trabekelwerk und den uveoskleralen Weg. Timolol, ein nicht selektiver Betablocker, vermindert die Bildung von Kammerwasser im Ziliarkörper. Timolol kann nach Aufnahme über die Schleimhäute auch Puls, Blutdruck und Bronchien beeinflussen.","nebenwirkungen":{"sehrHaeufig":["Augenrötung (Bindehauthyperämie)","Wimpernwachstum"],"haeufig":["Kopfschmerzen","Oberflächliche Hornhautentzündung, Hornhauterosion","Brennen, Stechen, Jucken, Fremdkörpergefühl, trockenes Auge, Augenschmerzen","Lidrötung, Lichtempfindlichkeit, Augenausfluss, Sehstörungen","Dunklere Lidhaut, vermehrtes Haarwachstum um das Auge","Schnupfen (Rhinitis)"],"gelegentlich":["Regenbogenhautentzündung (Iritis)","Bindehautschwellung, Lidschmerzen, Augenermüdung","Einwachsende Wimpern (Trichiasis)","Atemnot"],"unbekannt":["Langsamer Puls (Bradykardie), Herzrhythmusstörungen, Blutdruckabfall","Asthma, Bronchospasmus","Makulaödem (Netzhautschwellung)","Eingesunkene Augen (Vertiefung der Lidfurche)","Dauerhafte Braunfärbung der Iris","Schwindel, Schlafstörungen, Albträume, Müdigkeit","Allergische Reaktionen"]},"schwangerschaft":"Keine ausreichenden Daten; nur anwenden, wenn es ärztlich klar notwendig ist. Bei Anwendung bis zur Geburt das Neugeborene auf Betablocker-Wirkungen (langsamer Puls, Unterzuckerung) überwachen.","stillzeit":"Timolol geht in die Muttermilch über, zu Bimatoprost fehlen Daten – in der Stillzeit nicht anwenden.","hinweise":["Nach dem Eintropfen das Auge 1–2 Minuten schliessen und den inneren Augenwinkel sanft zudrücken – so gelangt weniger Wirkstoff ins Blut.","Überschüssige Tropfen von der Lidhaut abwischen, um Verfärbungen und Haarwuchs um das Auge zu vermindern.","Bei Asthma, Herzkrankheiten oder vor einer Operation die Anwendung der Augentropfen ärztlich angeben.","Bei mehreren Augenmitteln mindestens 5 Minuten Abstand einhalten."],"darreichung":["Augentropfen"]},"bimekizumab":{"wirkmechanismus":"Hemmt zwei eng verwandte Entzündungsbotenstoffe, die bei Schuppenflechte und entzündlichen Gelenk- und Wirbelsäulenerkrankungen eine zentrale Rolle spielen. Bimekizumab ist ein humanisierter monoklonaler IgG1-Antikörper, der sowohl Interleukin-17A als auch Interleukin-17F (und das Heterodimer IL-17A/F) bindet und deren Wirkung am IL-17-Rezeptor verhindert. Dadurch werden die Entzündung in Haut, Gelenken und Wirbelsäule sowie die übermässige Hautzellvermehrung gebremst.","nebenwirkungen":{"sehrHaeufig":["Infektionen der oberen Atemwege"],"haeufig":["Candida-Infektionen in Mund und Rachen (Soor)","Hautpilzinfektionen (Tinea)","Ohrentzündungen","Herpes-simplex-Infektionen","Magen-Darm-Entzündung (Gastroenteritis)","Kopfschmerzen","Ausschlag, Ekzem, Akne, Haarbalgentzündung","Reaktionen an der Einstichstelle, Müdigkeit"],"gelegentlich":["Candida-Infektionen von Haut und Schleimhäuten (inkl. Speiseröhre)","Bindehautentzündung","Neutropenie (Mangel an weissen Blutkörperchen)","Entzündliche Darmerkrankung (Morbus Crohn, Colitis ulcerosa)"]},"schwangerschaft":"Vorsichtshalber vermeiden. Frauen im gebärfähigen Alter sollen während und mindestens 17 Wochen nach der Behandlung zuverlässig verhüten.","stillzeit":"Nicht bekannt, ob Bimekizumab in die Muttermilch übergeht; über Stillen oder Behandlung entscheidet die Ärztin oder der Arzt.","hinweise":["Weisse Beläge, Brennen im Mund oder Schluckbeschwerden können auf Soor hinweisen – ärztlich behandeln lassen.","Bei neuem blutigem oder schleimigem Durchfall oder Bauchschmerzen ärztlich abklären (entzündliche Darmerkrankung).","Vor Beginn Tuberkulose-Test; keine Lebendimpfungen während der Behandlung."],"darreichung":["Injektionslösung im Fertigpen oder in der Fertigspritze (unter die Haut)"]},"binimetinib":{"wirkmechanismus":"Bremst das Wachstum von Melanomzellen, deren Wachstumssignal durch eine BRAF-Mutation dauerhaft eingeschaltet ist. Binimetinib ist ein reversibler, ATP-unabhängiger (allosterischer) Hemmer der Kinasen MEK1 und MEK2 im MAPK-Signalweg und blockiert die Aktivierung von ERK. In Kombination mit dem BRAF-Hemmer Encorafenib wird der Signalweg doppelt gehemmt, was die Wirkung verstärkt und Resistenzen verzögert.","nebenwirkungen":{"sehrHaeufig":["Müdigkeit, Fieber, periphere Ödeme (Wassereinlagerungen)","Übelkeit, Erbrechen, Durchfall, Bauchschmerzen, Verstopfung","Sehstörungen, seröse Netzhautablösung","Gelenk- und Muskelschmerzen, Myopathie","Bluthochdruck, Blutungen","Hautausschlag, trockene Haut, Juckreiz, Haarausfall","Kopfschmerzen, Schwindel, periphere Neuropathie","Anämie; Anstieg von CK, Leberwerten und Kreatinin"],"haeufig":["Linksventrikuläre Dysfunktion (Abnahme der Herzleistung)","Venöse Thromboembolien (Thrombose, Lungenembolie)","Uveitis (Augenentzündung)","Kolitis (Darmentzündung)","Überempfindlichkeitsreaktionen","Plattenepithelkarzinom und Basaliom der Haut"],"gelegentlich":["Rhabdomyolyse (Muskelzerfall)","Pankreatitis (Bauchspeicheldrüsenentzündung)","Fazialisparese (Gesichtslähmung)"],"unbekannt":["Pneumonitis (Lungenentzündung ohne Infektion)"]},"schwangerschaft":"Nicht anwenden (im Tierversuch fruchtschädigend). Frauen müssen während und mindestens 1 Monat nach der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Zweimal täglich im Abstand von etwa 12 Stunden einnehmen, mit oder ohne Essen.","Sehstörungen, Atemnot, Brustschmerzen, Beinschwellung oder starke Muskelschmerzen sofort ärztlich melden.","Regelmässige Kontrollen: Herzfunktion, Blutdruck, Augen, Haut, Leberwerte und CK."],"darreichung":["Filmtabletten"]},"biotin":{"wirkmechanismus":"Biotin ist ein Vitamin, das für den Stoffwechsel von Fetten, Kohlenhydraten und Eiweissen nötig ist und das Wachstum von Haut, Haaren und Nägeln unterstützt. Es dient als Coenzym von Carboxylasen (z. B. Acetyl-CoA-Carboxylase, Pyruvatcarboxylase), die Kohlendioxid auf Stoffwechselprodukte übertragen. Ein echter Biotinmangel ist selten; er kommt z. B. bei angeborenem Biotinidase-Mangel, langer künstlicher Ernährung oder unter bestimmten Antiepileptika vor.","nebenwirkungen":{"sehrSelten":["Allergische Hautreaktionen (Nesselsucht)"]},"schwangerschaft":"Biotin in Dosen im Bereich des Tagesbedarfs ist unbedenklich; höhere Dosen nur nach ärztlicher Rücksprache, da wenige Daten vorliegen.","stillzeit":"Biotin geht in die Muttermilch über; höhere Dosen nur nach ärztlicher Rücksprache.","hinweise":["Vor Blutuntersuchungen die Biotin-Einnahme angeben; je nach Test wird empfohlen, Biotin einige Tage vorher zu pausieren.","Nägel und Haare wachsen langsam – eine Wirkung zeigt sich frühestens nach einigen Wochen bis Monaten."],"darreichung":["Tabletten"]},"biperiden":{"wirkmechanismus":"Stellt das Gleichgewicht zwischen den Botenstoffen Dopamin und Acetylcholin im Gehirn teilweise wieder her und vermindert so Zittern, Steifigkeit und Muskelkrämpfe. Biperiden blockiert zentrale Muskarinrezeptoren (bevorzugt M1) im Striatum, wo bei Dopaminmangel ein relatives Acetylcholin-Übergewicht besteht. Die periphere anticholinerge Wirkung erklärt Nebenwirkungen wie Mundtrockenheit, Verstopfung und Harnverhalt.","nebenwirkungen":{"unbekannt":["Müdigkeit, Schwindel, Benommenheit","Unruhe, Erregung, Angst, Euphorie, Verwirrtheit, Halluzinationen, Gedächtnisstörungen (besonders bei höherer Dosis und älteren Menschen)","Mundtrockenheit, verminderte Schweissbildung","Akkommodationsstörungen, erweiterte Pupillen, Lichtempfindlichkeit, Auslösung eines Engwinkelglaukoms","Herzrasen (Tachykardie)","Verstopfung, Magenbeschwerden, Übelkeit","Störungen beim Wasserlassen bis Harnverhalt","Dyskinesien, Koordinations- und Sprechstörungen, Krampfanfälle"]},"schwangerschaft":"Nur begrenzte Erfahrungen; nur nach strenger ärztlicher Abwägung anwenden.","stillzeit":"Geht in die Muttermilch über und kann die Milchbildung hemmen; nicht stillen.","hinweise":["Nicht abrupt absetzen – Gefahr der Verschlechterung der Parkinson-Symptome oder von Entzugserscheinungen.","Bei Mundtrockenheit helfen zuckerfreie Kaugummis; bei Augenschmerzen, Harnverhalt oder Verwirrtheit ärztlich melden.","Bei Hitze auf Überwärmung achten (vermindertes Schwitzen).","Alkohol meiden; Vorsicht beim Autofahren."],"darreichung":["Tabletten","Retardtabletten","Injektionslösung"]},"bisacodyl":{"wirkmechanismus":"Regt die Darmbewegung an und sorgt dafür, dass mehr Wasser im Darm bleibt, sodass der Stuhl weicher wird. Bisacodyl ist eine Vorstufe (Prodrug): Im Darm wird es durch Enzyme der Darmschleimhaut und Bakterien zum Wirkstoff BHPM (Bis-(p-hydroxyphenyl)-pyridyl-2-methan) umgewandelt. Dieser reizt die Nerven der Dickdarmschleimhaut, verstärkt die Peristaltik und hemmt die Rückaufnahme von Wasser und Salzen bzw. fördert deren Ausscheidung in den Darm. Die magensaftresistente Hülle verhindert eine Freisetzung im Magen.","nebenwirkungen":{"haeufig":["Bauchkrämpfe, Bauchschmerzen","Übelkeit","Durchfall"],"gelegentlich":["Erbrechen, Bauchbeschwerden","Blut im Stuhl (Hämatochezie)","Beschwerden und Brennen im Analbereich (Zäpfchen)","Schwindel"],"selten":["Überempfindlichkeitsreaktionen, Angioödem, Anaphylaxie","Dehydratation (Flüssigkeitsmangel)","Kolitis (Dickdarmentzündung), auch ischämische Kolitis","Kurze Ohnmacht (Synkope) beim Stuhlgang"]},"schwangerschaft":"Es sind keine schädlichen Wirkungen bekannt; dennoch nur nach ärztlicher Rücksprache und wenn Ernährungsmassnahmen nicht ausreichen.","stillzeit":"Der Wirkstoff geht nicht in nennenswertem Mass in die Muttermilch über; Anwendung in der Stillzeit möglich.","hinweise":["Dragées unzerkaut schlucken, nicht zusammen mit Milch oder Säurebindern; abends eingenommen wirken sie am nächsten Morgen.","Abführmittel nur kurzzeitig anwenden; bei länger dauernder Verstopfung ärztlich abklären lassen.","Für die Vorbeugung von Verstopfung sind ballaststoffreiche Ernährung, genügend Trinken und Bewegung erste Wahl."],"darreichung":["Magensaftresistente Dragées","Zäpfchen"]},"bismutsubcitrat-kalium-metronidazol-tetracyclin":{"wirkmechanismus":"Bekämpft den Magenkeim Helicobacter pylori mit drei Wirkstoffen gleichzeitig; das zusätzlich eingenommene Omeprazol senkt die Magensäure und verbessert die Wirkung. Bismut wirkt direkt antibakteriell, stört die Haftung der Bakterien an der Schleimhaut und schützt den Geschwürsgrund. Metronidazol wird im Bakterium zu reaktiven Produkten umgewandelt, die dessen Erbgut (DNA) schädigen. Tetracyclin hemmt die bakterielle Eiweisssynthese durch Bindung an die 30S-Untereinheit der Ribosomen. Die Kombination wirkt auch bei Keimen, die gegen Clarithromycin resistent sind.","nebenwirkungen":{"sehrHaeufig":["Schwarzfärbung des Stuhls (harmlos, durch Bismut)","Durchfall","Übelkeit","Geschmacksstörungen (Metallgeschmack)"],"haeufig":["Kopfschmerzen, Schwindel","Erbrechen, Bauchschmerzen, Verstopfung, Blähungen","Mundtrockenheit","Scheidenpilz","Schwäche, Müdigkeit","Erhöhte Leberwerte"],"gelegentlich":["Schläfrigkeit, Kribbeln oder Taubheitsgefühl, Zittern","Pilzinfektion im Mund (Soor)","Zungen- und Mundschleimhautentzündung, Zungenverfärbung","Appetitlosigkeit","Hautausschlag, Juckreiz, Nesselsucht"],"unbekannt":["Pseudomembranöse Kolitis (schwere Darmentzündung durch Clostridioides difficile)","Anaphylaxie und schwere Hautreaktionen (z. B. Stevens-Johnson-Syndrom, DRESS)","Periphere Neuropathie, Enzephalopathie, Krampfanfälle, aseptische Meningitis","Schwere Leberschädigung","Lichtempfindlichkeit (Photosensibilisierung)","Blutbildveränderungen (Leukopenie, Neutropenie, Thrombozytopenie)"]},"schwangerschaft":"Kontraindiziert: Tetracyclin schädigt Zähne und Knochen des ungeborenen Kindes, Metronidazol tritt in den kindlichen Kreislauf über.","stillzeit":"Kontraindiziert; Metronidazol und Tetracyclin gehen in die Muttermilch über.","hinweise":["Kapseln ganz, in aufrechter Haltung und mit einem grossen Glas Wasser schlucken, nicht im Liegen (Reizung der Speiseröhre).","Während der Behandlung und mindestens 3 Tage danach keinen Alkohol trinken.","Die Behandlung zusammen mit Omeprazol über die volle Dauer durchführen; nicht mit Milch einnehmen.","Starke Sonne und Solarium meiden; schwarzer Stuhl ist harmlos."],"darreichung":["Hartkapseln"]},"bisoprolol":{"wirkmechanismus":"Verlangsamt den Herzschlag und entlastet das Herz, indem es die Wirkung der Stresshormone am Herzen blockiert. Bisoprolol ist ein hochselektiver Hemmer der Beta-1-Rezeptoren ohne Eigenwirkung am Rezeptor; es senkt Herzfrequenz, Kontraktionskraft, Sauerstoffverbrauch und die Reninfreisetzung. Es wird je zur Hälfte in der Leber (u. a. CYP3A4) abgebaut und unverändert über die Niere ausgeschieden.","nebenwirkungen":{"sehrHaeufig":["Bradykardie (langsamer Puls) – v. a. bei Behandlung der Herzinsuffizienz"],"haeufig":["Schwindel, Kopfschmerzen (v. a. zu Therapiebeginn)","Kältegefühl oder Taubheit in Händen und Füssen","Übelkeit, Erbrechen, Durchfall, Verstopfung","Müdigkeit, Erschöpfung","Verschlechterung einer Herzinsuffizienz, Blutdruckabfall (bei Herzinsuffizienz-Patienten)"],"gelegentlich":["AV-Überleitungsstörungen","Blutdruckabfall beim Aufstehen","Schlafstörungen, Depression","Bronchospasmus bei Asthma oder COPD","Muskelschwäche, Muskelkrämpfe"],"selten":["Albträume, Halluzinationen","Ohnmacht (Synkope)","Verminderter Tränenfluss (Kontaktlinsen)","Hörstörungen","Hepatitis, erhöhte Leberwerte, erhöhte Blutfette","Potenzstörungen","Überempfindlichkeitsreaktionen (Juckreiz, Rötung, Ausschlag)"],"sehrSelten":["Bindehautentzündung","Haarausfall","Auslösung oder Verschlechterung einer Psoriasis"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung (mögliche Wachstumsverzögerung des Kindes). Das Neugeborene auf langsamen Puls und Unterzuckerung überwachen.","stillzeit":"Nicht ausreichend untersucht; Stillen während der Behandlung wird nicht empfohlen.","hinweise":["Nicht abrupt absetzen – schrittweise ausschleichen, besonders bei koronarer Herzkrankheit.","Bei Herzinsuffizienz wird die Dosis langsam über Wochen gesteigert; anfänglich können Beschwerden zunehmen.","Morgens unabhängig vom Essen einnehmen; Fahrtüchtigkeit kann zu Beginn und mit Alkohol beeinträchtigt sein."],"darreichung":["Filmtabletten"]},"bivalirudin":{"wirkmechanismus":"Verhindert während eines Eingriffs an den Herzkranzgefässen die Bildung von Blutgerinnseln. Bivalirudin ist ein synthetisches Peptid aus 20 Aminosäuren, das dem Blutegel-Wirkstoff Hirudin nachempfunden ist. Es bindet direkt an das aktive Zentrum und an die Fibrinogen-Bindungsstelle von Thrombin und hemmt so freies und gerinnselgebundenes Thrombin. Da Thrombin Bivalirudin langsam spaltet und es zudem über die Niere ausgeschieden wird, klingt die Wirkung nach Infusionsende rasch ab (Halbwertszeit rund 25 Minuten).","nebenwirkungen":{"haeufig":["Leichte Blutungen, vor allem an der Punktionsstelle"],"gelegentlich":["Schwere Blutungen (z. B. Magen-Darm- oder Harnwegsblutung)","Anämie (Blutarmut), Thrombozytopenie","Blutergüsse (Hämatome)","Übelkeit, Erbrechen","Kopfschmerzen","Hautausschlag"],"selten":["Hirnblutung","Herzbeutelblutung und Herzbeuteltamponade","Langsamer Puls, Herzrhythmusstörungen","Überempfindlichkeitsreaktionen bis Anaphylaxie"],"unbekannt":["Stentthrombose (Gerinnsel im Stent), vor allem beim Herzinfarkt mit ST-Hebung"]},"schwangerschaft":"Nur begrenzte Daten; nur anwenden, wenn eindeutig notwendig.","stillzeit":"Unbekannt, ob Bivalirudin in die Muttermilch übergeht; nur mit Vorsicht anwenden.","hinweise":["Wird nur im Spital während des Eingriffs gegeben; danach folgt eine Überwachung auf Blutungen und Stentthrombose.","Nach dem Eingriff Blutungen an der Punktionsstelle, Brustschmerzen oder Atemnot sofort melden."],"darreichung":["Pulver für ein Konzentrat zur Herstellung einer Injektions- bzw. Infusionslösung"]},"bleomycin":{"wirkmechanismus":"Zerstört die Erbsubstanz von Krebszellen. Bleomycin ist ein Glykopeptid-Antibiotikum aus Streptomyces verticillus, das an die DNA bindet und zusammen mit Eisen und Sauerstoff freie Radikale bildet, die Einzel- und Doppelstrangbrüche verursachen. Da Haut und Lunge wenig vom abbauenden Enzym Bleomycin-Hydrolase besitzen, treten dort die typischen Nebenwirkungen auf, während das Knochenmark kaum geschädigt wird.","nebenwirkungen":{"sehrHaeufig":["Hautveränderungen (Rötung, Verdickung, Pigmentierung, Streifen) und Nagelveränderungen","Mundschleimhautentzündung","Haarausfall","Fieber und Schüttelfrost am Tag der Gabe","Appetitlosigkeit, Gewichtsverlust"],"haeufig":["Pneumonitis (Lungenentzündung) und Lungenfibrose, teils tödlich","Übelkeit, Erbrechen"],"unbekannt":["Akute idiosynkratische Reaktion mit Blutdruckabfall, Verwirrtheit, Fieber und Atemnot (v. a. bei Lymphomen)","Raynaud-Phänomen, Herzinfarkt, Schlaganfall, thrombotische Mikroangiopathie","Anaphylaxie und andere Überempfindlichkeitsreaktionen","Schmerzen an der Einstichstelle oder im Tumor","Leichte Knochenmarkhemmung"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Notwendigkeit; Bleomycin kann das Ungeborene schädigen. Frauen und Männer müssen während der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Vor jeder Narkose oder Operation – auch Jahre nach der Behandlung – auf die Bleomycin-Therapie hinweisen (Sauerstoff kann die Lunge schädigen).","Neuer Husten oder Atemnot sofort melden; die Lungenfunktion wird regelmässig kontrolliert.","Nicht rauchen.","Fieber kurz nach der Injektion ist häufig und meist vorübergehend."],"darreichung":["Pulver zur Herstellung einer Injektionslösung"]},"blinatumomab":{"wirkmechanismus":"Bringt körpereigene Abwehrzellen (T-Zellen) direkt an die Leukämiezellen heran, damit diese zerstört werden. Blinatumomab ist ein bispezifisches Antikörperkonstrukt, das gleichzeitig an CD19 auf gesunden und bösartigen B-Zellen und an CD3 auf T-Zellen bindet. Dadurch wird die T-Zelle aktiviert, setzt Zytokine und zytotoxische Proteine frei und tötet die CD19-positive Zelle. Wegen der sehr kurzen Halbwertszeit wird es als ununterbrochene Infusion über jeweils 4 Wochen gegeben.","nebenwirkungen":{"sehrHaeufig":["Infektionen (bakteriell, viral, durch Pilze)","Neutropenie (auch mit Fieber), Anämie, Thrombozytopenie","Zytokin-Freisetzungs-Syndrom (Fieber, Schüttelfrost, Blutdruckabfall)","Infusionsbedingte Reaktionen","Kopfschmerzen, Tremor (Zittern)","Übelkeit, Durchfall, Verstopfung","Hautausschlag","Ödeme (Wassereinlagerungen), Müdigkeit"],"haeufig":["Sepsis (Blutvergiftung), Lungenentzündung","Enzephalopathie (Hirnfunktionsstörung), Verwirrtheit, Sprachstörungen","Krampfanfälle","Tumorlysesyndrom","Erhöhte Leberwerte und Bilirubin","Verminderte Immunglobuline (Antikörpermangel)","Hypertonie (Bluthochdruck)"],"gelegentlich":["Pankreatitis (Bauchspeicheldrüsenentzündung)","Kapillarlecksyndrom (Flüssigkeitsaustritt aus den Gefässen)","Hämophagozytische Lymphohistiozytose (lebensbedrohliche Überaktivierung des Immunsystems)","Zytokinsturm"],"unbekannt":["Leukoenzephalopathie (Veränderungen der weissen Hirnsubstanz)"]},"schwangerschaft":"Kann beim Ungeborenen die B-Zellen vermindern; nur anwenden, wenn der Nutzen klar überwiegt. Frauen im gebärfähigen Alter verhüten während und mindestens 48 Stunden nach der Behandlung.","stillzeit":"Kontraindiziert: während und mindestens 48 Stunden nach der Behandlung nicht stillen.","hinweise":["Behandlungsbeginn im Spital; die Dauerinfusion läuft danach über eine tragbare Pumpe – Pumpe nicht selbst verstellen, Alarme sofort melden.","Während der Behandlung kein Auto fahren und keine Maschinen bedienen (Verwirrtheit und Krampfanfälle möglich).","Fieber, Atemnot, Verwirrtheit, Zittern, Sprach- oder Gleichgewichtsstörungen sofort melden.","Blutbild und Leberwerte werden regelmässig kontrolliert."],"darreichung":["Pulver zur Herstellung einer Infusionslösung (Dauerinfusion)"]},"blutgerinnungsfaktor-ix":{"wirkmechanismus":"Ersetzt den fehlenden Gerinnungsfaktor IX und normalisiert so vorübergehend die Blutgerinnung. Faktor IX wird durch Faktor XIa oder den Komplex aus Gewebefaktor und Faktor VIIa aktiviert; Faktor IXa bildet zusammen mit Faktor VIIIa den sogenannten Tenase-Komplex, der Faktor X aktiviert und damit die Thrombinbildung ermöglicht. Präparate mit verlängerter Halbwertszeit (Fusion mit Fc-Fragment oder Albumin, PEGylierung) erlauben Injektionsabstände von einer bis zwei Wochen.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Schwindel","Übelkeit","Überempfindlichkeitsreaktionen (z. B. Hautausschlag, Nesselsucht)","Reaktionen an der Injektionsstelle","Hemmkörperbildung gegen Faktor IX (vor allem bei zuvor unbehandelten Patienten)"],"unbekannt":["Anaphylaktische Reaktionen (schwere allergische Reaktion)","Thromboembolische Ereignisse","Nephrotisches Syndrom (nach Immuntoleranzbehandlung bei Hemmkörpern)","Ungenügendes Ansprechen auf die Behandlung"]},"schwangerschaft":"Hämophilie B betrifft selten Frauen; Erfahrungen in der Schwangerschaft fehlen – nur bei klarer Notwendigkeit anwenden.","stillzeit":"Nur bei klarer Notwendigkeit anwenden; Daten fehlen.","hinweise":["Wird in die Vene gespritzt, nach Schulung oft als Heimbehandlung; ein Behandlungstagebuch mit Chargennummer führen.","Bei ungenügender Wirkung Hemmkörper bestimmen lassen.","Bei Zeichen einer allergischen Reaktion (Ausschlag, Engegefühl in der Brust, Atemnot) Injektion sofort abbrechen und Notfall alarmieren."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"blutgerinnungsfaktor-viii":{"wirkmechanismus":"Ersetzt den fehlenden Gerinnungsfaktor VIII und normalisiert so vorübergehend die Blutgerinnung. Aktivierter Faktor VIII wirkt als Kofaktor von Faktor IXa und beschleunigt die Aktivierung von Faktor X; dadurch entstehen genügend Thrombin und ein stabiles Fibringerinnsel. Rekombinante Präparate werden gentechnisch hergestellt; Varianten mit verlängerter Halbwertszeit (z. B. durch PEGylierung oder Fc-Fusion) erlauben seltenere Injektionen.","nebenwirkungen":{"sehrHaeufig":["Hemmkörperbildung gegen Faktor VIII bei zuvor unbehandelten Patienten (meist Kleinkinder)"],"haeufig":["Kopfschmerzen"],"gelegentlich":["Hemmkörperbildung bei bereits behandelten Patienten","Schwindel","Hautausschlag, Juckreiz, Nesselsucht","Reaktionen an der Injektionsstelle"],"unbekannt":["Anaphylaktische Reaktionen (schwere allergische Reaktion)","Fieber, Schüttelfrost","Übelkeit"]},"schwangerschaft":"Hämophilie A betrifft selten Frauen; Erfahrungen in der Schwangerschaft fehlen – nur bei klarer Notwendigkeit anwenden.","stillzeit":"Nur bei klarer Notwendigkeit anwenden; Daten fehlen.","hinweise":["Wird in die Vene gespritzt, nach Schulung oft als Heimbehandlung; ein Behandlungstagebuch mit Chargennummer führen.","Bei ungenügender Wirkung oder häufigeren Blutungen Hemmkörper bestimmen lassen.","Bei Zeichen einer allergischen Reaktion (Ausschlag, Engegefühl in der Brust, Atemnot, Schwindel) Injektion sofort stoppen und Notfall alarmieren."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"blutgerinnungsfaktor-xiii":{"wirkmechanismus":"Festigt Blutgerinnsel, damit sie nicht zu früh wieder aufgelöst werden. Faktor XIII wird durch Thrombin in Gegenwart von Calcium zu Faktor XIIIa aktiviert, einem Enzym (Transglutaminase), das die Fibrinstränge quervernetzt und Alpha-2-Antiplasmin einbaut. Dadurch wird das Gerinnsel mechanisch stabil und widerstandsfähig gegen die Fibrinolyse; Faktor XIII ist zudem an der Wundheilung beteiligt.","nebenwirkungen":{"unbekannt":["Allergische Reaktionen (Hautausschlag, Juckreiz, Nesselsucht) bis zum anaphylaktischen Schock","Fieber","Hemmkörperbildung gegen Faktor XIII mit ungenügender Wirkung"]},"schwangerschaft":"Nur bei klarer Notwendigkeit anwenden. Erfahrungen bei Schwangeren mit Faktor-XIII-Mangel, die zur Verhinderung von Fehlgeburten behandelt wurden, zeigen keine schädlichen Wirkungen.","stillzeit":"Nur bei klarer Notwendigkeit anwenden; Daten fehlen.","hinweise":["Wird langsam in die Vene gespritzt; die Dosis richtet sich nach dem Faktor-XIII-Spiegel und wird von einem spezialisierten Zentrum festgelegt.","Bei Allergiezeichen die Injektion sofort stoppen.","Aus menschlichem Plasma hergestellt: Chargennummer dokumentieren; Impfungen gegen Hepatitis A und B werden empfohlen."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektions- oder Infusionslösung"]},"bortezomib":{"wirkmechanismus":"Blockiert die «Müllabfuhr» der Zelle, sodass sich in Krebszellen schädliche Eiweisse anstauen und die Zellen absterben. Bortezomib hemmt reversibel die chymotrypsinähnliche Aktivität des 26S-Proteasoms. Dadurch werden regulatorische Proteine nicht mehr abgebaut, was unter anderem den Signalweg NF-κB hemmt und den programmierten Zelltod auslöst. Myelomzellen reagieren darauf besonders empfindlich.","nebenwirkungen":{"sehrHaeufig":["Thrombozytopenie, Neutropenie, Anämie","Periphere Neuropathie (Kribbeln, Brennen, Taubheit)","Übelkeit, Erbrechen, Durchfall, Verstopfung","Appetitlosigkeit","Müdigkeit, Schwäche, Fieber","Muskelschmerzen"],"haeufig":["Hypotonie (tiefer Blutdruck), auch beim Aufstehen, Ohnmacht","Herpes zoster (Gürtelrose)","Lungenentzündung und andere Infektionen","Schwindel, Kopfschmerzen","Hautausschlag, Juckreiz","Ödeme (Wassereinlagerungen), Atemnot","Magen-Darm-Blutungen","Verschlechterung der Nierenfunktion"],"gelegentlich":["Herzinsuffizienz, Herzrhythmusstörungen","Tumorlysesyndrom","Leberfunktionsstörung"],"selten":["Posteriores reversibles Enzephalopathie-Syndrom (PRES)","Akute diffuse infiltrative Lungenerkrankung","Ischämische Kolitis (Darmdurchblutungsstörung)","Schwere Hautreaktionen"],"sehrSelten":["Progressive multifokale Leukenzephalopathie (PML, schwere Hirninfektion)"],"unbekannt":["Thrombotische Mikroangiopathie (Blutgerinnsel in kleinen Gefässen)"]},"schwangerschaft":"Nicht anwenden. Frauen sollen während und bis 8 Monate, Männer bis 3 Monate nach der Behandlung sicher verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Meist wird eine vorbeugende Behandlung gegen Gürtelrose (z. B. Aciclovir) verschrieben – regelmässig einnehmen.","Ausreichend trinken; bei Schwindel oder Ohnmachtsneigung nicht Auto fahren.","Kribbeln, Brennen oder Taubheit in Händen und Füssen früh melden."],"darreichung":["Pulver oder Lösung zur Injektion (unter die Haut oder in die Vene)"]},"bosentan":{"wirkmechanismus":"Erweitert die Lungengefässe und bremst deren krankhaften Umbau. Bosentan blockiert beide Endothelin-Rezeptoren (ETA und ETB) und hemmt so die Wirkung von Endothelin-1, das bei Lungenhochdruck vermehrt gebildet wird und Gefässe verengt, verdickt und vernarben lässt. Der Widerstand in den Lungengefässen sinkt, das rechte Herz wird entlastet und die Belastbarkeit verbessert sich.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Ödeme, Flüssigkeitsretention (Wassereinlagerungen)"],"haeufig":["Anämie (Blutarmut), Hämoglobinabfall","Erhöhte Leberwerte (Transaminasen)","Überempfindlichkeitsreaktionen (Hautentzündung, Juckreiz, Ausschlag)","Synkope (Ohnmacht), Herzklopfen","Gesichtsrötung (Flush), Blutdruckabfall","Verstopfte Nase","Sodbrennen (Reflux), Durchfall"],"gelegentlich":["Thrombozytopenie, Neutropenie (Mangel an Blutplättchen bzw. weissen Blutkörperchen)","Leberentzündung mit Gelbsucht"],"selten":["Anaphylaxie (schwere allergische Reaktion), Angioödem","Leberzirrhose, Leberversagen"],"unbekannt":["Verschwommenes Sehen"]},"schwangerschaft":"Kontraindiziert (fruchtschädigend). Schwangerschaftstest vor Beginn und monatlich; zuverlässige Verhütung, wobei hormonelle Methoden allein nicht genügen.","stillzeit":"Nicht stillen – Bosentan geht in die Muttermilch über.","hinweise":["Leberwerte monatlich kontrollieren; bei Übelkeit, Erbrechen, Fieber, Bauchschmerzen, Gelbsucht oder dunklem Urin sofort ärztlich melden.","Frauen im gebärfähigen Alter: monatlicher Schwangerschaftstest und zuverlässige Verhütung (die Pille allein reicht nicht).","Rasche Gewichtszunahme oder Beinschwellungen melden (Flüssigkeitseinlagerung)."],"darreichung":["Filmtabletten","Tabletten zur Herstellung einer Suspension zum Einnehmen"]},"bosutinib":{"wirkmechanismus":"Blockiert gezielt das krankhafte Enzym, das die Leukämiezellen bei CML wachsen lässt. Bosutinib hemmt die BCR-ABL-Tyrosinkinase sowie Kinasen der SRC-Familie; KIT und PDGF-Rezeptoren werden dagegen kaum gehemmt. Es wirkt gegen viele Imatinib-resistente BCR-ABL-Mutationen, nicht aber gegen T315I und V299L.","nebenwirkungen":{"sehrHaeufig":["Durchfall (sehr oft, meist in den ersten Wochen)","Übelkeit, Erbrechen, Bauchschmerzen","Hautausschlag","Mangel an Blutplättchen, weissen und roten Blutkörperchen","Erhöhte Leberwerte und Lipase","Müdigkeit, Fieber, Kopfschmerzen","Atemwegsinfekte, Husten","Gelenkschmerzen, Wassereinlagerungen, Appetitlosigkeit"],"haeufig":["Pleura- und Herzbeutelerguss (Wasser im Brustfell bzw. Herzbeutel)","QT-Verlängerung im EKG","Akute Nierenschädigung, Abnahme der Nierenfunktion","Leberschädigung (Hepatotoxizität)","Lungenentzündung","Juckreiz, Nesselsucht, Akne","Flüssigkeitsmangel (Dehydratation)"],"gelegentlich":["Arzneimittelbedingte Leberschädigung mit Gelbsucht","Akute Pankreatitis (Bauchspeicheldrüsenentzündung)","Lungenödem"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (schwere Hautreaktionen)","Reaktivierung einer Hepatitis B"]},"schwangerschaft":"Nicht anwenden, ausser es ist zwingend notwendig (im Tierversuch fruchtschädigend). Frauen im gebärfähigen Alter müssen während und mindestens 1 Monat nach der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Einmal täglich mit einer Mahlzeit einnehmen; keine Grapefruit, kein Grapefruitsaft und kein Johanniskraut.","Durchfall früh mit Durchfallmitteln und ausreichend Flüssigkeit behandeln; starken oder anhaltenden Durchfall ärztlich melden.","Leberwerte in den ersten 3 Monaten monatlich sowie Blutbild und Nierenfunktion regelmässig kontrollieren."],"darreichung":["Filmtabletten"]},"botulinumtoxin-typ-a":{"wirkmechanismus":"Lähmt den behandelten Muskel oder die Schweissdrüse vorübergehend, indem es die Signalübertragung vom Nerv blockiert. Botulinumtoxin Typ A wird in die Nervenendigungen aufgenommen und spaltet dort das Protein SNAP-25, das für die Freisetzung von Acetylcholin nötig ist. Ohne Acetylcholin kann sich der Muskel nicht mehr zusammenziehen und die Schweissdrüse keinen Schweiss mehr bilden. Die Wirkung setzt nach einigen Tagen ein und lässt nach etwa 3–6 Monaten nach, wenn neue Nervenendigungen gebildet werden; die Einheiten der verschiedenen Präparate sind nicht austauschbar.","nebenwirkungen":{"sehrHaeufig":["Hängendes Oberlid (Ptosis) bei Behandlung des Lidkrampfs","Harnwegsinfekte nach Injektion in die Blase"],"haeufig":["Schmerzen, Bluterguss oder Rötung an der Einstichstelle","Muskelschwäche in der Umgebung der Injektionsstelle","Schluckbeschwerden (Dysphagie) nach Injektionen im Halsbereich","Kopf- und Nackenschmerzen","Harnverhalt nach Injektion in die Blase (Katheterisierung kann nötig werden)","Trockene oder gereizte Augen, Tränenfluss nach Injektion im Augenbereich"],"unbekannt":["Ausbreitung der Wirkung fern der Injektionsstelle mit allgemeiner Muskelschwäche, Doppelbildern, Schluck- und Atemstörungen (in Einzelfällen tödlich)","Aspirationspneumonie (Lungenentzündung durch Verschlucken)","Anaphylaxie und andere schwere allergische Reaktionen","Herzrhythmusstörungen und Herzinfarkt bei Herzvorerkrankungen","Engwinkelglaukom nach Behandlung im Augenbereich"]},"schwangerschaft":"Nicht empfohlen; Anwendung nur, wenn unbedingt nötig. Ästhetische Behandlungen in der Schwangerschaft unterlassen.","stillzeit":"Nicht empfohlen, da unbekannt ist, ob der Wirkstoff in die Muttermilch übergeht.","hinweise":["Nur von erfahrenen Ärztinnen und Ärzten anwenden lassen; die Einheiten der verschiedenen Präparate sind nicht austauschbar.","Bei Schluck-, Sprech- oder Atembeschwerden nach der Injektion sofort ärztliche Hilfe holen.","Die Wirkung setzt nach einigen Tagen ein und hält meist 3–6 Monate.","Muskelschwäche, hängende Lider oder Sehstörungen können die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Pulver zur Herstellung einer Injektionslösung"]},"brentuximab-vedotin":{"wirkmechanismus":"Bringt ein Zellgift gezielt in Lymphomzellen mit dem Oberflächenmerkmal CD30. Der chimäre IgG1-Antikörper ist über einen durch Enzyme spaltbaren Linker an Monomethylauristatin E (MMAE) gekoppelt. Nach Bindung an CD30 wird das Konjugat in die Zelle aufgenommen; dort wird MMAE freigesetzt, zerstört das Mikrotubuli-Netzwerk, stoppt die Zellteilung und löst den Zelltod aus.","nebenwirkungen":{"sehrHaeufig":["Infektionen, auch der oberen Atemwege","Periphere sensorische Neuropathie (Kribbeln, Taubheit)","Neutropenie (Mangel an weissen Blutkörperchen)","Durchfall, Übelkeit, Erbrechen, Verstopfung, Bauchschmerzen","Müdigkeit, Fieber","Gelenk- und Muskelschmerzen","Husten, Atemnot","Juckreiz, Haarausfall, Gewichtsabnahme"],"haeufig":["Periphere motorische Neuropathie (Muskelschwäche)","Anämie, Thrombozytopenie, febrile Neutropenie","Gürtelrose, Lungenentzündung, Mundsoor","Hyperglykämie (erhöhter Blutzucker)","Erhöhte Leberwerte","Schwindel","Infusionsreaktionen","Hautausschlag, Rückenschmerzen, Schüttelfrost"],"gelegentlich":["Tumorlysesyndrom","Akute Pankreatitis","Stevens-Johnson-Syndrom","Septischer Schock, Pneumocystis-Pneumonie"],"unbekannt":["Progressive multifokale Leukenzephalopathie (PML, schwere Hirninfektion)","Toxische epidermale Nekrolyse","Schwere Magen-Darm-Komplikationen (Darmverschluss, Perforation, Blutung)","Gewebeschäden bei Austritt der Infusion (Extravasation)"]},"schwangerschaft":"Nicht anwenden, ausser der Nutzen überwiegt klar: Das Zellgift MMAE schädigt im Tierversuch das Ungeborene. Frauen und Männer mit Partnerin verhüten während der Behandlung und 6 Monate danach.","stillzeit":"Während der Behandlung nicht stillen (ärztliche Abwägung).","hinweise":["Kribbeln, Taubheitsgefühl, brennende Schmerzen oder Schwäche in Händen und Füssen früh melden – die Dosis kann angepasst werden.","Starke Bauchschmerzen, neue Verwirrtheit, Seh- oder Sprachstörungen, Atemnot oder Hautblasen sofort melden.","Blutbild und Blutzucker werden vor jeder Gabe kontrolliert.","Andere Medikamente, z. B. Antimykotika oder Antibiotika, mit dem Behandlungsteam abstimmen."],"darreichung":["Pulver für ein Infusionskonzentrat"]},"brexpiprazol":{"wirkmechanismus":"Gleicht die Signalübertragung durch Dopamin und Serotonin im Gehirn aus und mildert so psychotische Symptome. Brexpiprazol ist ein Partialagonist an Dopamin-D2- und Serotonin-5-HT1A-Rezeptoren und ein Antagonist an Serotonin-5-HT2A- sowie Alpha-1B- und Alpha-2C-adrenergen Rezeptoren. Am D2-Rezeptor hat es eine geringere Eigenaktivität als Aripiprazol. Es wird über CYP3A4 und CYP2D6 abgebaut.","nebenwirkungen":{"haeufig":["Gewichtszunahme","Akathisie (Sitzunruhe, Bewegungsdrang)","Schwindel, Zittern, Sedierung","Durchfall, Übelkeit, Oberbauchschmerzen","Hautausschlag","Erhöhte Kreatinkinase (Muskelenzym) im Blut"],"gelegentlich":["Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen)","Parkinsonismus"],"unbekannt":["Malignes neuroleptisches Syndrom (Fieber, Muskelsteifigkeit, Bewusstseinsstörung)","Krampfanfälle","Spätdyskinesien (unwillkürliche Bewegungen)","Spielsucht und andere Impulskontrollstörungen","Suizidgedanken und suizidales Verhalten","Venöse Thromboembolien (Blutgerinnsel)","Entzugssymptome beim Neugeborenen nach Einnahme in der Schwangerschaft"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Bei Einnahme im letzten Drittel können beim Neugeborenen Bewegungsstörungen und Entzugssymptome auftreten.","stillzeit":"Ob Brexpiprazol in die Muttermilch übergeht, ist beim Menschen nicht bekannt; ärztlich entscheiden, ob gestillt oder behandelt wird.","hinweise":["Einmal täglich, unabhängig von den Mahlzeiten einnehmen.","Kann müde oder schwindlig machen – Vorsicht beim Autofahren, Alkohol meiden.","Neu auftretende Spielsucht, Kaufsucht oder Essattacken ärztlich melden."],"darreichung":["Filmtabletten"]},"brigatinib":{"wirkmechanismus":"Blockiert gezielt das veränderte Wachstumssignal-Enzym ALK in Lungenkrebszellen. Brigatinib ist ein ALK-Hemmer der zweiten Generation, der auch ROS1 hemmt und gegen viele ALK-Resistenzmutationen wirksam ist. Es gelangt ins Gehirn und wirkt auch gegen Hirnmetastasen.","nebenwirkungen":{"sehrHaeufig":["Erhöhte Werte von Leberenzymen, CK (Muskelenzym), Lipase und Amylase","Erhöhter Blutzucker, Elektrolytstörungen","Blutarmut","Kopfschmerzen, periphere Neuropathie (Nervenstörungen), Schwindel","Bluthochdruck","Husten, Atemnot","Übelkeit, Durchfall, Erbrechen, Bauchschmerzen, Verstopfung","Hautausschlag, Juckreiz, Muskel- und Gelenkschmerzen, Müdigkeit, Ödeme"],"haeufig":["Pneumonitis (Lungenentzündung ohne Erreger), besonders in der ersten Behandlungswoche","Langsamer Puls (Bradykardie), QT-Verlängerung im EKG","Sehstörungen","Lichtempfindlichkeit (Photosensibilität)","Schlaflosigkeit, Gedächtnisstörung, Geschmacksstörung"],"gelegentlich":["Pankreatitis (Bauchspeicheldrüsenentzündung)"]},"schwangerschaft":"Nicht anwenden, ausser es ist zwingend notwendig. Frauen im gebärfähigen Alter müssen während und mindestens 4 Monate nach der Behandlung zuverlässig nichthormonal verhüten, Männer mit Partnerin im gebärfähigen Alter während und mindestens 3 Monate danach.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Einmal täglich unabhängig von den Mahlzeiten; in der ersten Woche wird eine niedrigere Dosis eingenommen.","Neue oder zunehmende Atemnot oder Husten – besonders in der ersten Woche – sofort ärztlich melden.","Blutdruck, Puls, Blutzucker, CK sowie Leber- und Pankreaswerte regelmässig kontrollieren; Sonnenschutz verwenden.","Keine Grapefruit und kein Johanniskraut."],"darreichung":["Filmtabletten"]},"brimonidin":{"wirkmechanismus":"Senkt den Augeninnendruck bzw. verengt die erweiterten Hautgefässe. Brimonidin stimuliert Alpha-2-Adrenozeptoren: Im Auge vermindert es die Bildung von Kammerwasser und verbessert dessen Abfluss über den uveoskleralen Weg. In der Haut zieht es die oberflächlichen Blutgefässe zusammen und reduziert so die Rötung für einige Stunden. Gelangt es in den Kreislauf, kann es Blutdruck und Puls senken und müde machen.","nebenwirkungen":{"sehrHaeufig":["Augentropfen: Augenrötung, Brennen, Stechen, Juckreiz, Fremdkörpergefühl","Augentropfen: allergische Bindehautentzündung (oft verzögert nach Monaten)","Augentropfen: Mundtrockenheit, Müdigkeit, Schläfrigkeit, Kopfschmerzen","Verschwommenes Sehen"],"haeufig":["Augentropfen: Lidschwellung, Lichtempfindlichkeit, Hornhautschäden","Schwindel, Geschmacksstörungen","Magen-Darm-Beschwerden, Schwächegefühl","Gel: Rötung, Flush, Juckreiz, Brennen der Haut"],"gelegentlich":["Herzklopfen, Herzrhythmusstörungen","Depression","Gel: Verschlechterung der Rosazea, Hautreizung, Kältegefühl der Haut","Nasentrockenheit"],"selten":["Atemnot","Gel: Angioödem (Schwellung)"],"sehrSelten":["Ohnmacht (Synkope), Blutdruckabfall oder -anstieg","Regenbogenhautentzündung (Iritis), Pupillenverengung"],"unbekannt":["Bradykardie (langsamer Puls)","Allergische Hautreaktionen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; beim Menschen nicht ausreichend untersucht.","stillzeit":"Augentropfen sollen in der Stillzeit nicht angewendet werden; auch das Gel wird nicht empfohlen.","hinweise":["Kann müde machen und die Sicht kurz verschwimmen lassen – Vorsicht beim Autofahren.","Augentropfen: nach dem Eintropfen den inneren Augenwinkel 1–2 Minuten zudrücken; zu anderen Augentropfen 5 Minuten Abstand.","Gel: nur erbsengrosse Menge einmal täglich im Gesicht verteilen, Augen und Lippen aussparen, danach Hände waschen."],"darreichung":["Augentropfen","Gel"]},"brimonidin-timolol":{"wirkmechanismus":"Senkt den Augeninnendruck über zwei Wege. Brimonidin, ein selektiver Alpha-2-Rezeptor-Agonist, vermindert die Kammerwasserbildung und verbessert den Abfluss über den uveoskleralen Weg. Timolol, ein nicht selektiver Betablocker, drosselt die Kammerwasserproduktion im Ziliarkörper. Beide Wirkstoffe können nach Aufnahme in den Kreislauf auch Blutdruck, Puls und Wachheit beeinflussen.","nebenwirkungen":{"sehrHaeufig":["Augenrötung (Bindehauthyperämie)","Brennen im Auge"],"haeufig":["Allergische Bindehautentzündung, Bindehautfollikel","Augenjucken, Stechen, Fremdkörpergefühl, trockenes Auge, Tränenfluss, Augenausfluss","Oberflächliche Hornhautentzündung, Hornhauterosion, Lidrandentzündung","Lidschwellung, -rötung und -juckreiz, Sehstörungen","Schläfrigkeit, Kopfschmerzen, Depression","Mundtrockenheit, Schwäche (Asthenie)","Bluthochdruck"],"gelegentlich":["Herzinsuffizienz, Herzrhythmusstörungen","Schwindel, Ohnmacht (Synkope)","Schnupfen, trockene Nase","Übelkeit, Geschmacksstörungen"],"unbekannt":["Langsamer Puls (Bradykardie), Blutdruckabfall","Bronchospasmus, Atemnot","Allergische Haut- und Allgemeinreaktionen","Müdigkeit, Schlafstörungen"]},"schwangerschaft":"Keine ausreichenden Daten; nur anwenden, wenn es ärztlich klar notwendig ist. Bei Anwendung bis zur Geburt das Neugeborene auf Betablocker-Wirkungen (langsamer Puls, Unterzuckerung) überwachen.","stillzeit":"Timolol geht in die Muttermilch über, Brimonidin vermutlich ebenfalls – in der Stillzeit nicht anwenden.","hinweise":["Nach dem Eintropfen das Auge 1–2 Minuten schliessen und den inneren Augenwinkel sanft zudrücken – so gelangt weniger Wirkstoff ins Blut.","Kann müde machen und die Sicht kurz trüben – Vorsicht beim Autofahren; Alkohol meiden.","Bei Asthma, Herzkrankheiten, Depression oder vor einer Operation die Anwendung ärztlich angeben.","Bei mehreren Augenmitteln mindestens 5 Minuten Abstand einhalten."],"darreichung":["Augentropfen"]},"brinzolamid":{"wirkmechanismus":"Senkt den Augeninnendruck, indem weniger Kammerwasser gebildet wird. Brinzolamid hemmt die Carboanhydrase II im Ziliarkörper; dadurch wird weniger Bicarbonat gebildet und der Flüssigkeitstransport ins Augeninnere verlangsamt. Ein Teil gelangt in den Kreislauf und reichert sich in den roten Blutkörperchen an; eine relevante Wirkung auf den Säure-Basen-Haushalt ist bei Augentropfen aber selten. Chemisch ist Brinzolamid ein Sulfonamid.","nebenwirkungen":{"haeufig":["Bitterer oder ungewöhnlicher Geschmack (Dysgeusie)","Verschwommenes Sehen","Augenreizung, Augenschmerzen, Fremdkörpergefühl","Augenrötung"],"gelegentlich":["Hornhautentzündung und -schäden (Keratitis, Erosion)","Trockenes Auge, Augenjucken, Lidrandentzündung, Bindehautentzündung, Lichtempfindlichkeit","Kopfschmerzen, Schwindel, Schläfrigkeit","Übelkeit, Durchfall, Mundtrockenheit","Nasenbluten, Rachenreizung, Atemnot"],"unbekannt":["Überempfindlichkeitsreaktionen","Ohrgeräusche (Tinnitus)","Herzrhythmusstörungen, Herzrasen","Haarausfall, Hautausschlag","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (sehr schwere Hautreaktionen)"]},"schwangerschaft":"Keine ausreichenden Daten, im Tierversuch fruchtschädigend. Nicht empfohlen; Frauen im gebärfähigen Alter sollen während der Behandlung verhüten.","stillzeit":"Nicht bekannt, ob Brinzolamid in die Muttermilch übergeht; nur nach ärztlicher Abwägung.","hinweise":["Vor Gebrauch gut schütteln.","Nach dem Eintropfen das Auge schliessen oder den inneren Augenwinkel 1–2 Minuten sanft zudrücken.","Bei mehreren Augentropfen mindestens 5 Minuten Abstand halten; Kontaktlinsen vorher herausnehmen."],"darreichung":["Augentropfen (Suspension)"]},"brinzolamid-timolol":{"wirkmechanismus":"Senkt den Augeninnendruck, indem die Bildung von Kammerwasser auf zwei Wegen gedrosselt wird. Brinzolamid hemmt die Carboanhydrase II im Ziliarkörper und vermindert so die Bicarbonat- und Flüssigkeitsbildung. Timolol, ein nicht selektiver Betablocker, verringert die Kammerwasserproduktion zusätzlich. Ein Teil beider Wirkstoffe gelangt in den Kreislauf; vor allem Timolol kann Puls, Blutdruck und Bronchien beeinflussen.","nebenwirkungen":{"haeufig":["Verschwommenes Sehen","Augenschmerzen, Augenreizung, Fremdkörpergefühl","Geschmacksstörung (bitterer Geschmack)"],"gelegentlich":["Hornhautentzündung und Hornhauterosion, trockenes Auge","Augenrötung, Augenausfluss, Augenjucken, Lidrandentzündung","Blutdruckabfall","Husten, Rachenschmerzen, Fliessschnupfen"],"unbekannt":["Langsamer Puls (Bradykardie), Herzrhythmusstörungen, Herzinsuffizienz","Bronchospasmus, Atemnot, Asthma","Schwindel, Kopfschmerzen, Müdigkeit, Depression","Kalte Hände und Füsse","Allergische Reaktionen, Hautausschlag","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (sehr schwere Hautreaktionen)"]},"schwangerschaft":"Nicht anwenden, ausser es ist ärztlich klar notwendig (Brinzolamid im Tierversuch fruchtschädigend). Bei Anwendung bis zur Geburt das Neugeborene auf Betablocker-Wirkungen überwachen.","stillzeit":"Timolol geht in die Muttermilch über; ein Risiko für den Säugling ist nicht auszuschliessen. Ärztlich abwägen, ob abgestillt oder die Behandlung unterbrochen wird.","hinweise":["Vor Gebrauch gut schütteln.","Nach dem Eintropfen das Auge 1–2 Minuten schliessen und den inneren Augenwinkel sanft zudrücken – so gelangt weniger Wirkstoff ins Blut.","Bei Asthma, Herzkrankheiten oder vor einer Operation die Anwendung der Augentropfen ärztlich angeben.","Bei mehreren Augenmitteln mindestens 5 Minuten Abstand einhalten."],"darreichung":["Augentropfen (Suspension)"]},"brivaracetam":{"wirkmechanismus":"Vermindert die übermässige Erregbarkeit von Nervenzellen im Gehirn. Brivaracetam bindet mit hoher Affinität an das synaptische Vesikelprotein 2A (SV2A), das an der Freisetzung von Botenstoffen beteiligt ist, und senkt so die Anfallsbereitschaft. Es wirkt ähnlich wie Levetiracetam, bindet aber stärker und selektiver.","nebenwirkungen":{"sehrHaeufig":["Schwindel","Schläfrigkeit"],"haeufig":["Grippe, Infekte der oberen Atemwege, Husten","Verminderter Appetit","Depression, Angst, Schlaflosigkeit, Reizbarkeit","Krampfanfall, Drehschwindel","Übelkeit, Erbrechen, Verstopfung","Müdigkeit"],"gelegentlich":["Neutropenie (Mangel an weissen Blutkörperchen)","Allergische Sofortreaktion","Suizidgedanken","Psychotische Störungen, Aggressivität, Unruhe"]},"schwangerschaft":"Nur bei klarer Notwendigkeit nach ärztlicher Abwägung; eine wirksame Behandlung nicht eigenmächtig absetzen.","stillzeit":"Brivaracetam geht in die Muttermilch über; nach ärztlicher Abwägung entweder abstillen oder die Behandlung ändern.","hinweise":["Unabhängig von den Mahlzeiten einnehmen.","Nicht abrupt absetzen – Gefahr gehäufter Anfälle.","Alkohol meiden; Reaktionsvermögen und Fahrtüchtigkeit können beeinträchtigt sein."],"darreichung":["Filmtabletten","Lösung zum Einnehmen","Injektions- oder Infusionslösung"]},"brivudin":{"wirkmechanismus":"Hemmt die Vermehrung des Varizella-Zoster-Virus, das Windpocken und Gürtelrose verursacht. Brivudin ist ein Thymidin-Analogon, das in infizierten Zellen bevorzugt durch die virale Thymidinkinase phosphoryliert wird; das entstehende Brivudin-Triphosphat hemmt die virale DNA-Polymerase und damit die Bildung neuer Virus-DNA. Das Abbauprodukt Bromovinyluracil hemmt irreversibel das Enzym Dihydropyrimidin-Dehydrogenase (DPD), das Fluoropyrimidine wie 5-Fluorouracil abbaut – daher die lebensgefährliche Wechselwirkung mit diesen Krebsmitteln.","nebenwirkungen":{"haeufig":["Übelkeit"],"gelegentlich":["Kopfschmerzen, Schwindel, Schläfrigkeit","Schlaflosigkeit, Angstgefühle","Erbrechen, Durchfall, Verdauungsbeschwerden, Bauchschmerzen, Verstopfung","Appetitlosigkeit","Erhöhte Leberwerte, Fettleber","Hautausschlag, Juckreiz, Überempfindlichkeitsreaktionen","Veränderungen des Blutbilds (z. B. weniger Granulozyten, Anämie, Eosinophilie)","Müdigkeit, Schwäche"],"selten":["Hepatitis (Leberentzündung), Bilirubinanstieg","Verwirrtheit, Halluzinationen","Geschmacksstörungen","Blutdruckabfall","Thrombozytopenie (Mangel an Blutplättchen)","Knochenschmerzen"],"unbekannt":["Schwere Leberschäden bis zum akuten Leberversagen (Einzelfälle)","Schwere Hautreaktionen"]},"schwangerschaft":"In der Schwangerschaft kontraindiziert (keine ausreichenden Erfahrungen).","stillzeit":"In der Stillzeit kontraindiziert.","hinweise":["Einmal täglich möglichst zur gleichen Tageszeit während 7 Tagen einnehmen; die Behandlung nicht verlängern.","Vor der Einnahme unbedingt angeben, ob eine Krebsbehandlung läuft, geplant ist oder kürzlich stattfand – auch 5-Fluorouracil-Cremes gegen Hautveränderungen zählen.","Mit Fluoropyrimidinen (z. B. Capecitabin) frühestens 4 Wochen nach der letzten Brivudin-Tablette beginnen."],"darreichung":["Tabletten"]},"bromazepam":{"wirkmechanismus":"Wirkt angstlösend, beruhigend und muskelentspannend, indem es die hemmenden Signale im Gehirn verstärkt. Bromazepam bindet an die Benzodiazepin-Bindungsstelle des GABA-A-Rezeptors und verstärkt die Wirkung des hemmenden Botenstoffs GABA (vermehrter Chlorid-Einstrom, verminderte Erregbarkeit der Nervenzellen). In höheren Dosen wirkt es auch schlaffördernd und krampflösend. Die Halbwertszeit beträgt etwa 20 Stunden.","nebenwirkungen":{"unbekannt":["Müdigkeit, Schläfrigkeit und verminderte Aufmerksamkeit (auch am Folgetag)","Muskelschwäche, Gangunsicherheit (Ataxie), Stürze","Schwindel, Kopfschmerzen, Doppeltsehen","Verwirrtheit, Gedächtnislücken (anterograde Amnesie)","Paradoxe Reaktionen wie Unruhe, Reizbarkeit, Aggressivität, Albträume, Halluzinationen","Abhängigkeit; Entzugs- und Absetzsymptome (Schlaflosigkeit, Angst, Krampfanfälle)","Atemdepression (abgeschwächte Atmung)","Magen-Darm-Beschwerden, Hautreaktionen"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit, besonders im ersten Drittel. Bei Einnahme gegen Ende der Schwangerschaft oder unter der Geburt drohen beim Neugeborenen Muskelschlaffheit, Trinkschwäche, Unterkühlung, Atemprobleme und Entzugssymptome.","stillzeit":"Bromazepam geht in die Muttermilch über; während der Einnahme soll nicht gestillt werden.","hinweise":["Kann die Fahrtüchtigkeit und das Reaktionsvermögen stark beeinträchtigen – auch noch am nächsten Tag.","Keinen Alkohol trinken: verstärkte Dämpfung.","Möglichst kurz anwenden (in der Regel höchstens 8–12 Wochen inklusive Ausschleichen), da sich eine Abhängigkeit entwickeln kann.","Nach längerer Einnahme nicht abrupt absetzen, sondern nach ärztlicher Anleitung schrittweise reduzieren."],"darreichung":["Tabletten"]},"bromhexin":{"wirkmechanismus":"Verflüssigt zähen Bronchialschleim und erleichtert das Abhusten. Bromhexin ist ein synthetischer Abkömmling des Pflanzenstoffs Vasicin; es lockert die Faserstruktur des Schleims (Sekretolyse) und fördert den Abtransport durch die Flimmerhärchen. Im Körper wird es unter anderem zu Ambroxol umgewandelt, das zur Wirkung beiträgt.","nebenwirkungen":{"gelegentlich":["Übelkeit, Erbrechen, Durchfall, Oberbauchschmerzen","Fieber"],"selten":["Überempfindlichkeitsreaktionen (Hautausschlag, Nesselsucht)"],"unbekannt":["Anaphylaxie bis zum Schock, Angioödem, Juckreiz","Bronchospasmus (Verkrampfung der Atemwege)","Schwere Hautreaktionen (Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, akute generalisierte exanthematische Pustulose)"]},"schwangerschaft":"Begrenzte Erfahrungen; vorsichtshalber während der Schwangerschaft nicht anwenden.","stillzeit":"Ein Übergang in die Muttermilch ist zu erwarten; in der Stillzeit nicht empfohlen.","hinweise":["Nicht mit Hustenstillern kombinieren.","Viel trinken unterstützt die Schleimlösung.","Bei neuem Hautausschlag oder Blasen an Haut und Schleimhäuten sofort absetzen und ärztlich abklären lassen."],"darreichung":["Tabletten","Sirup"]},"bromocriptin":{"wirkmechanismus":"Wirkt im Körper wie der Botenstoff Dopamin. Bromocriptin ist ein Abkömmling der Mutterkornalkaloide und stimuliert Dopamin-D2-Rezeptoren. In der Hirnanhangdrüse hemmt das die Ausschüttung von Prolaktin (und bei Akromegalie von Wachstumshormon); in den Basalganglien gleicht es den Dopaminmangel bei Parkinson teilweise aus.","nebenwirkungen":{"haeufig":["Übelkeit, Erbrechen, Verstopfung","Kopfschmerzen, Schwindel, Schläfrigkeit","Verstopfte Nase"],"gelegentlich":["Blutdruckabfall beim Aufstehen, bis zum Kollaps","Verwirrtheit, Unruhe, Halluzinationen","Dyskinesien (unwillkürliche Bewegungen)","Mundtrockenheit, Wadenkrämpfe","Allergische Hautreaktionen, Haarausfall","Müdigkeit"],"selten":["Fibrosen an Lunge, Rippenfell und Herzbeutel, retroperitoneale Fibrose","Psychotische Störungen, Schlaflosigkeit","Herzrhythmusstörungen (zu schneller oder zu langsamer Puls)","Magen-Darm-Geschwüre und -Blutungen","Sehstörungen, Ohrgeräusche","Durchblutungsstörungen der Finger und Zehen (Raynaud)"],"sehrSelten":["Plötzliches Einschlafen","Bei Anwendung nach der Geburt: starker Blutdruckanstieg, Herzinfarkt, Krampfanfälle, Schlaganfall"],"unbekannt":["Impulskontrollstörungen (z. B. Spielsucht, Kaufsucht)","Herzklappenerkrankungen","Malignes neuroleptisches Syndrom bei abruptem Absetzen"]},"schwangerschaft":"Bei Eintritt einer Schwangerschaft in der Regel absetzen (Ausnahme: grössere Prolaktinome nach ärztlicher Entscheidung). Bei Bluthochdruck in der Schwangerschaft kontraindiziert.","stillzeit":"Bromocriptin unterdrückt die Milchbildung; bei Stillwunsch nicht anwenden.","hinweise":["Mit dem Essen einnehmen; die Dosis wird langsam gesteigert, um Übelkeit und Blutdruckabfall zu vermeiden.","Bei Langzeitbehandlung regelmässige Kontrollen (Herzultraschall, Lunge, Blutdruck).","Plötzliches Einschlafen möglich – dann nicht Auto fahren.","Nach der Geburt bei starken Kopfschmerzen, Brustschmerzen, Sehstörungen oder Blutdruckanstieg sofort ärztliche Hilfe holen."],"darreichung":["Tabletten"]},"budesonid":{"wirkmechanismus":"Dämpft Entzündungen direkt dort, wo es angewendet wird – im Darm, in der Speiseröhre, in den Bronchien oder in der Nase. Budesonid ist ein stark wirksames Glukokortikoid, das an den Glukokortikoidrezeptor in den Zellen bindet und die Bildung entzündungsfördernder Botenstoffe (Zytokine, Prostaglandine, Leukotriene) sowie die Einwanderung von Entzündungszellen hemmt. Nach dem Schlucken werden rund 85–90 % beim ersten Durchgang durch die Leber über CYP3A4 abgebaut, deshalb sind Kortison-Nebenwirkungen im ganzen Körper deutlich seltener als etwa bei Prednison. Spezielle Darreichungen setzen den Wirkstoff gezielt im Dünndarm oder Dickdarm frei.","nebenwirkungen":{"haeufig":["Pilzinfektion (Soor) in Mund und Rachen bei Inhalation bzw. in der Speiseröhre bei Schmelztabletten","Heiserkeit, Rachenreizung und Husten (Inhalation)","Nasenbluten und Reizung der Nasenschleimhaut (Nasenspray)","Kortisontypische Veränderungen wie Vollmondgesicht (bei Einnahme)","Hypokaliämie (Kaliummangel) bei Einnahme","Verdauungsbeschwerden, Muskelkrämpfe, Herzklopfen","Nervosität, Schlafstörungen, Stimmungsschwankungen","Hautausschlag, Nesselsucht"],"gelegentlich":["Angst, Zittern (Tremor), Depression","Verschwommenes Sehen"],"selten":["Grauer Star (Katarakt), grüner Star (Glaukom)","Paradoxer Bronchospasmus (Verkrampfung der Atemwege nach Inhalation)","Blaue Flecken","Verhaltensänderungen und Aggressivität, besonders bei Kindern","Unterdrückung der Nebennierenfunktion"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion)","Wachstumsverzögerung bei Kindern","Abnahme der Knochendichte","Durchbruch der Nasenscheidewand (Nasenspray)"],"unbekannt":["Chorioretinopathia centralis serosa (Netzhauterkrankung mit Sehstörung)"]},"schwangerschaft":"Inhaliertes Budesonid ist gut untersucht und kann in der Schwangerschaft angewendet werden. Zum Einnehmen nur nach ärztlicher Abwägung.","stillzeit":"Geht in sehr geringen Mengen in die Muttermilch über; Inhalation in üblicher Dosis vertretbar, Einnahme nach ärztlicher Abwägung.","hinweise":["Nach dem Inhalieren den Mund mit Wasser ausspülen oder die Zähne putzen (beugt Soor und Heiserkeit vor).","Zur Inhalation regelmässig anwenden, auch ohne Beschwerden; im akuten Asthmaanfall das Notfallspray benutzen.","Kapseln und Tabletten unzerkaut schlucken; während der Behandlung keinen Grapefruitsaft trinken.","Nach längerer Einnahme nicht abrupt absetzen, sondern nach ärztlicher Anweisung ausschleichen."],"darreichung":["Kapseln (magensaftresistent bzw. mit verzögerter Freisetzung)","Retardtabletten","Schmelztabletten","Rektalschaum","Klysma (Einlauf)","Pulver zur Inhalation","Suspension zur Inhalation (Vernebler)","Nasenspray"]},"budesonid-glycopyrronium-formoterol":{"wirkmechanismus":"Kombiniert Entzündungshemmung mit zweifacher Bronchienerweiterung. Budesonid ist ein Glukokortikoid, das in der Bronchialschleimhaut die Bildung entzündungsfördernder Botenstoffe hemmt. Glycopyrronium blockiert Muskarinrezeptoren (M3) der Bronchialmuskulatur, Formoterol stimuliert Beta-2-Rezeptoren und erhöht cAMP; beides entspannt die Atemwege. Budesonid wird in der Leber über CYP3A4 abgebaut, weshalb starke CYP3A4-Hemmer seine Spiegel deutlich erhöhen.","nebenwirkungen":{"haeufig":["Candidose (Pilzbefall) in Mund und Rachen","Lungenentzündung (Pneumonie)","Harnwegsinfekt","Hyperglykämie (erhöhter Blutzucker)","Angst, Schlaflosigkeit","Kopfschmerzen","Herzklopfen (Palpitationen)","Heiserkeit (Dysphonie), Husten, Übelkeit, Muskelkrämpfe"],"gelegentlich":["Überempfindlichkeitsreaktionen","Depression, Unruhe, Nervosität","Zittern (Tremor), Schwindel","Angina pectoris, Tachykardie, Herzrhythmusstörungen (Vorhofflimmern, Extrasystolen)","Rachenreizung, Bronchospasmus","Mundtrockenheit","Blaue Flecken (Blutergüsse)","Harnverhalt"],"sehrSelten":["Zeichen systemischer Kortisonwirkung, z. B. Nebennierenunterfunktion","Verhaltensauffälligkeiten"],"unbekannt":["Angioödem (Schwellung von Gesicht, Lippen, Rachen)","Verschwommenes Sehen, grauer Star (Katarakt), grüner Star (Glaukom)"]},"schwangerschaft":"Nur begrenzte Erfahrungen; nur anwenden, wenn der erwartete Nutzen das mögliche Risiko für das Kind überwiegt. Formoterol kann die Wehen hemmen.","stillzeit":"Budesonid geht in geringen Mengen in die Muttermilch über, für Glycopyrronium und Formoterol fehlen Daten; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Morgens und abends regelmässig inhalieren; vor dem ersten Gebrauch und nach längerer Pause den Inhalator nach Anleitung vorbereiten.","Nach dem Inhalieren den Mund mit Wasser ausspülen und das Wasser ausspucken (Vorbeugung gegen Pilzbefall).","Nicht für akute Atemnot – dafür ein rasch wirksames Bedarfsspray verwenden.","Nicht eigenmächtig absetzen; Fieber, verfärbter Auswurf und zunehmende Atemnot können auf eine Lungenentzündung hinweisen – ärztlich abklären."],"darreichung":["Dosieraerosol"]},"bulevirtid":{"wirkmechanismus":"Verhindert, dass das Hepatitis-D-Virus in Leberzellen eindringt. Bulevirtid ist ein synthetisches Lipopeptid, das dem Bindungsabschnitt (pre-S1) der Hepatitis-B-Virushülle nachgebildet ist. Es bindet an den Gallensäuren-Transporter NTCP auf den Leberzellen, den Hepatitis-B- und -D-Viren als Eintrittsrezeptor benutzen, und blockiert ihn. Dadurch werden keine neuen Leberzellen infiziert; als Folge steigen die Gallensäuren im Blut an, meist ohne Beschwerden.","nebenwirkungen":{"sehrHaeufig":["Erhöhte Gallensäuren im Blut (meist ohne Beschwerden)","Kopfschmerzen","Juckreiz","Reaktionen an der Einstichstelle (Rötung, Schwellung, Schmerz, Juckreiz)"],"haeufig":["Eosinophilie (Vermehrung bestimmter weisser Blutkörperchen)","Schwindel","Übelkeit","Gelenkschmerzen","Müdigkeit","Grippeähnliche Beschwerden"],"unbekannt":["Überempfindlichkeitsreaktionen bis Anaphylaxie","Aufflammen der Hepatitis nach dem Absetzen"]},"schwangerschaft":"Keine Erfahrungen beim Menschen. Vorsichtshalber in der Schwangerschaft und bei Frauen im gebärfähigen Alter ohne Verhütung nicht anwenden.","stillzeit":"Nicht bekannt, ob Bulevirtid in die Muttermilch übergeht. Ärztlich entscheiden, ob abgestillt oder auf die Behandlung verzichtet wird.","hinweise":["Einmal täglich unter die Haut spritzen; nach Schulung ist die Selbstanwendung möglich. Einstichstelle wechseln.","Nicht eigenmächtig absetzen: die Hepatitis kann danach aufflammen.","Leberwerte und HDV-Viruslast werden regelmässig kontrolliert; eine Hepatitis-B-Behandlung wird nach Richtlinien weitergeführt."],"darreichung":["Pulver zur Herstellung einer Injektionslösung (unter die Haut)"]},"bumetanid":{"wirkmechanismus":"Schwemmt rasch und kräftig Wasser aus, indem es die Salzausscheidung über die Niere steigert. Bumetanid hemmt im aufsteigenden Teil der Henle-Schleife den Natrium-Kalium-2-Chlorid-Kotransporter, sodass grosse Mengen Natrium, Chlorid und Wasser ausgeschieden werden; auch Kalium, Magnesium und Calcium gehen vermehrt verloren. Die Wirkung setzt nach Einnahme innert etwa einer Stunde ein und hält einige Stunden an; gewichtsbezogen ist Bumetanid etwa 40-mal stärker als Furosemid.","nebenwirkungen":{"haeufig":["Hypokaliämie (Kaliummangel)","Hyponatriämie und Hypochlorämie (Natrium- und Chloridmangel)","Dehydratation (Flüssigkeitsmangel)","Hyperurikämie (erhöhte Harnsäure)","Schwindel, Kopfschmerzen, Müdigkeit","Blutdruckabfall beim Aufstehen"],"unbekannt":["Muskelkrämpfe","Hyperglykämie (erhöhter Blutzucker), Gichtanfall","Hörstörungen, Ohrensausen","Thrombozytopenie und andere Blutbildveränderungen","Schwere Hautreaktionen","Gynäkomastie (Brustvergrösserung beim Mann)","Akuter Harnverhalt","Akutes Nierenversagen"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit; nicht zur Behandlung von Schwangerschaftsödemen oder Schwangerschaftshochdruck (verminderte Durchblutung der Plazenta).","stillzeit":"Nicht empfohlen; kann die Milchbildung hemmen.","hinweise":["Morgens bzw. tagsüber einnehmen; die Wirkung setzt rasch ein.","Kalium, Natrium, Nierenwerte, Blutzucker und Harnsäure regelmässig kontrollieren; Körpergewicht beobachten.","Bei Schwindel, starkem Durst, Muskelkrämpfen oder Hörstörungen ärztlich melden.","Bei Durchfall, Erbrechen oder starkem Schwitzen droht Flüssigkeitsmangel – ärztlich abklären."],"darreichung":["Tabletten","Injektionslösung"]},"bupivacain":{"wirkmechanismus":"Betäubt örtlich, indem es die Weiterleitung von Nervensignalen – auch von Schmerzsignalen – vorübergehend unterbricht. Bupivacain blockiert die spannungsabhängigen Natriumkanäle der Nervenmembran und verhindert so die Entstehung und Fortleitung von Aktionspotenzialen. Die Wirkung setzt langsam ein, hält aber mehrere Stunden an. Gelangt zu viel davon ins Blut, blockiert es auch Natriumkanäle im Herzen und im Gehirn, was Herzrhythmusstörungen und Krampfanfälle auslösen kann.","nebenwirkungen":{"sehrHaeufig":["Hypotonie (Blutdruckabfall)","Übelkeit"],"haeufig":["Kribbeln (Parästhesien), Schwindel","Bradykardie (langsamer Puls)","Blutdruckanstieg","Erbrechen","Harnverhalt"],"gelegentlich":["Zeichen einer Vergiftung des Nervensystems: Taubheit um den Mund, Ohrgeräusche, Sehstörungen, Zittern, Krampfanfälle, Bewusstlosigkeit"],"selten":["Anaphylaxie (schwere allergische Reaktion)","Herzrhythmusstörungen, Herzstillstand","Nervenschäden, Lähmungen bis Querschnittlähmung, Arachnoiditis (Entzündung der Rückenmarkshäute)","Atemdepression","Doppeltsehen"]},"schwangerschaft":"Wird seit Jahrzehnten in der Geburtshilfe eingesetzt; im ersten Schwangerschaftsdrittel nur nach Abwägung. Die 0,75-%-Lösung ist für die Periduralanästhesie unter der Geburt kontraindiziert.","stillzeit":"Geht nur in sehr geringen Mengen in die Muttermilch über; Stillen ist möglich.","hinweise":["Nach einer rückenmarknahen Betäubung können Gefühl und Kraft in den Beinen über Stunden fehlen – nur mit Hilfe aufstehen.","Blutverdünnende Medikamente vor dem Eingriff unbedingt angeben.","Taubheit um den Mund, Ohrensausen, Metallgeschmack oder Unruhe sofort melden (mögliche Zeichen einer Überdosierung)."],"darreichung":["Injektionslösung","Hyperbare Injektionslösung (Spinalanästhesie)"]},"buprenorphin":{"wirkmechanismus":"Lindert Schmerzen und unterdrückt bei Opioidabhängigkeit das Verlangen und die Entzugssymptome. Buprenorphin ist ein Partialagonist am μ-Opioidrezeptor und ein Antagonist am κ-Rezeptor; es bindet sehr fest an den Rezeptor und löst sich nur langsam. Dadurch ist die Atemdämpfung bei alleiniger Anwendung begrenzt («Ceiling-Effekt»), doch es kann die Wirkung anderer Opioide abschwächen und bei Opioidabhängigen einen Entzug auslösen. Der Abbau erfolgt in der Leber über CYP3A4 zu Norbuprenorphin.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Kopfschmerzen","Schlaflosigkeit","Starkes Schwitzen","Rötung und Juckreiz an der Pflasterstelle","Entzugssymptome (bei Substitution)"],"haeufig":["Schwindel, Schläfrigkeit","Verstopfung, Erbrechen, Bauchschmerzen","Angst, Unruhe, Depression","Atemnot","Blutdruckabfall beim Aufstehen, Ohnmacht","Wassereinlagerungen, Müdigkeit, Schwäche","Muskel- und Gelenkschmerzen"],"selten":["Atemdepression (abgeschwächte Atmung)"],"unbekannt":["Anaphylaxie und Angioödem (schwere allergische Reaktionen)","Hepatitis, Leberversagen, Gelbsucht","Halluzinationen","Abhängigkeit","Entzugssyndrom beim Neugeborenen"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung; eine bestehende Substitutionsbehandlung wird in der Regel weitergeführt, das Schmerzpflaster soll in der Schwangerschaft nicht angewendet werden. Gegen Ende der Schwangerschaft Gefahr von Atemdepression und Entzugssyndrom beim Neugeborenen.","stillzeit":"Buprenorphin geht in geringen Mengen in die Muttermilch über. Unter Substitution ist Stillen nach ärztlicher Abwägung möglich; bei Schmerzbehandlung mit dem Pflaster wird vom Stillen abgeraten.","hinweise":["Sublingualtabletten unter der Zunge vollständig zergehen lassen, nicht schlucken oder kauen.","Kein Alkohol und keine Beruhigungsmittel ohne ärztliche Absprache – Gefahr lebensbedrohlicher Atemdämpfung; die Fahrtüchtigkeit kann eingeschränkt sein.","Pflaster keiner Wärme aussetzen; gebrauchte Pflaster gefaltet und für Kinder unerreichbar entsorgen.","Bei Substitution Leberwerte regelmässig kontrollieren."],"darreichung":["Sublingualtabletten","Transdermale Pflaster","Injektionslösung","Depot-Injektionslösung"]},"buprenorphin-naloxon":{"wirkmechanismus":"Buprenorphin dämpft Entzugserscheinungen und Suchtdruck; Naloxon soll das missbräuchliche Spritzen verhindern. Buprenorphin ist ein partieller Agonist am µ-Opioidrezeptor mit sehr starker Rezeptorbindung und ein Antagonist am κ-Rezeptor; wegen seines Ceiling-Effekts (Wirkung steigt ab einer gewissen Dosis nicht mehr weiter) ist das Risiko einer Atemdepression geringer als bei vollen Agonisten. Der Opioid-Antagonist Naloxon wird bei Einnahme unter der Zunge kaum aufgenommen; gespritzt wirkt er jedoch voll und löst Entzugssymptome aus. Buprenorphin wird hauptsächlich über CYP3A4 abgebaut.","nebenwirkungen":{"sehrHaeufig":["Schlaflosigkeit","Kopfschmerzen","Übelkeit","Verstopfung","Starkes Schwitzen","Entzugssymptome"],"haeufig":["Schläfrigkeit, Schwindel","Angst, Depression, Nervosität","Erbrechen, Bauchschmerzen, Durchfall","Libidoverlust, Erektionsstörungen","Wassereinlagerungen (Ödeme)","Hautausschlag, Juckreiz"],"unbekannt":["Atemdepression","Hepatitis bis Leberversagen","Anaphylaxie, Angioödem (schwere allergische Reaktionen)","Zahnschäden (Karies, Zahnverlust)","Blutdruckabfall beim Aufstehen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; beim Neugeborenen kann nach längerer Anwendung ein Entzugssyndrom auftreten, das überwacht werden muss.","stillzeit":"Buprenorphin geht in die Muttermilch über; vom Stillen wird abgeraten bzw. nur nach ärztlicher Abwägung.","hinweise":["Unter die Zunge legen und vollständig zergehen lassen (5–10 Minuten), nicht kauen oder schlucken; danach den Mund mit Wasser spülen (Zahnschutz).","Die erste Dosis erst bei deutlichen Entzugszeichen einnehmen, sonst kann ein Entzug ausgelöst werden.","Für Kinder unerreichbar aufbewahren; kein Alkohol und keine Beruhigungsmittel ohne ärztliche Absprache.","Kann die Fahrtüchtigkeit beeinträchtigen, besonders zu Beginn der Behandlung."],"darreichung":["Sublingualtabletten"]},"bupropion":{"wirkmechanismus":"Wirkt antriebssteigernd und stimmungsaufhellend, indem es die Botenstoffe Noradrenalin und Dopamin im Gehirn länger wirken lässt. Bupropion und sein wichtigster aktiver Abbaustoff Hydroxybupropion (gebildet über CYP2B6) hemmen die Wiederaufnahme von Noradrenalin und Dopamin in die Nervenzellen; auf Serotonin wirken sie kaum. Bei der Raucherentwöhnung mildert es vermutlich über das Belohnungssystem Rauchverlangen und Entzugssymptome. Bupropion ist zudem ein starker Hemmer des Leberenzyms CYP2D6.","nebenwirkungen":{"sehrHaeufig":["Schlaflosigkeit","Kopfschmerzen","Mundtrockenheit","Übelkeit, Erbrechen"],"haeufig":["Agitiertheit (Unruhe), Angst","Zittern (Tremor), Schwindel, Geschmacksstörungen","Appetitlosigkeit","Blutdruckanstieg (teils deutlich), Hautrötung (Flush)","Bauchschmerzen, Verstopfung","Hautausschlag, Juckreiz, Schwitzen","Sehstörungen, Ohrensausen (Tinnitus)","Fieber, Brustschmerzen, Schwäche"],"gelegentlich":["Depression, Verwirrtheit","Konzentrationsstörungen","Herzrasen (Tachykardie)","Gewichtsabnahme"],"selten":["Krampfanfälle (etwa 1 von 1000 Behandelten)"],"sehrSelten":["Schwere Überempfindlichkeitsreaktionen (Angioödem, Atemnot, anaphylaktischer Schock, Serumkrankheit-ähnliche Reaktionen)","Halluzinationen, Aggressivität, Wahnvorstellungen, Albträume","Erythema multiforme, Stevens-Johnson-Syndrom","Hepatitis, Gelbsucht, erhöhte Leberwerte","Blutzuckerschwankungen","Herzklopfen, Ohnmacht"],"unbekannt":["Suizidgedanken und suizidales Verhalten","Psychose","Hyponatriämie (Natriummangel)","Serotoninsyndrom (zusammen mit serotonergen Mitteln)","Blutbildveränderungen (Anämie, Leukopenie, Thrombozytopenie)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung; einige Studien weisen auf ein möglicherweise erhöhtes Risiko für angeborene Herzfehler hin. Zur Raucherentwöhnung in der Schwangerschaft nicht anwenden.","stillzeit":"Bupropion und seine Abbauprodukte gehen in die Muttermilch über; nur nach ärztlicher Abwägung (abstillen oder auf die Behandlung verzichten).","hinweise":["Retardtabletten ganz schlucken, nicht teilen, zerkauen oder zerdrücken (höheres Risiko für Krampfanfälle).","Höchstdosis nicht überschreiten; bei zweimal täglicher Einnahme (Raucherentwöhnung) mindestens 8 Stunden Abstand halten und nicht kurz vor dem Schlafengehen einnehmen.","Zur Raucherentwöhnung das Rauchstopp-Datum in der zweiten Behandlungswoche festlegen.","Blutdruck regelmässig kontrollieren; Alkohol meiden."],"darreichung":["Retardtabletten"]},"burosumab":{"wirkmechanismus":"Normalisiert den zu tiefen Phosphatspiegel, indem es ein überaktives Hormon abfängt. Burosumab ist ein humaner monoklonaler IgG1-Antikörper, der den Fibroblasten-Wachstumsfaktor 23 (FGF23) bindet und hemmt. Bei XLH ist FGF23 krankhaft erhöht und führt zu Phosphatverlust über die Niere und zu wenig aktivem Vitamin D. Die Hemmung steigert die Rückresorption von Phosphat in den Nierentubuli und die Bildung von 1,25-Dihydroxy-Vitamin-D, sodass das Phosphat im Blut ansteigt.","nebenwirkungen":{"sehrHaeufig":["Reaktionen an der Injektionsstelle (Rötung, Schwellung, Schmerz, Juckreiz)","Kopfschmerzen, Schwindel","Gliederschmerzen, Rückenschmerzen","Zahninfektionen und Zahnabszesse","Erniedrigtes Vitamin D im Blut","Hautausschlag","Fieber (bei Kindern)","Restless-Legs-Syndrom (unruhige Beine) und Verstopfung (bei Erwachsenen)"],"haeufig":["Erhöhtes Phosphat im Blut (Hyperphosphatämie)","Muskelkrämpfe"]},"schwangerschaft":"Keine ausreichenden Daten; Anwendung in der Schwangerschaft nicht empfohlen. Frauen im gebärfähigen Alter sollen wirksam verhüten.","stillzeit":"Es ist nicht bekannt, ob Burosumab in die Muttermilch übergeht; über Stillen oder Behandlung wird individuell entschieden.","hinweise":["Während der Behandlung keine Phosphattabletten und kein aktives Vitamin D (z. B. Calcitriol) einnehmen.","Phosphat im Blut, Nierenultraschall und Parathormon werden regelmässig kontrolliert.","Gute Zahnhygiene und regelmässige Zahnkontrollen (Zahnabszesse häufig)."],"darreichung":["Injektionslösung (subkutan)"]},"buspiron":{"wirkmechanismus":"Lindert Angst und Anspannung, ohne wesentlich zu sedieren oder die Muskeln zu entspannen. Buspiron ist ein Partialagonist an Serotonin-5-HT1A-Rezeptoren und bindet zudem mässig an Dopamin-D2-Rezeptoren. Anders als Benzodiazepine wirkt es nicht am GABA-A-Rezeptor; es wirkt deshalb nicht krampfhemmend und hat nach bisherigen Erfahrungen kein relevantes Abhängigkeitspotenzial. Die angstlösende Wirkung entwickelt sich erst nach 1–2 Wochen regelmässiger Einnahme.","nebenwirkungen":{"sehrHaeufig":["Schwindel","Kopfschmerzen","Schläfrigkeit"],"haeufig":["Nervosität, Schlaflosigkeit, Konzentrationsstörungen, Reizbarkeit","Verwirrtheit, depressive Verstimmung","Kribbeln (Parästhesien), Zittern, verschwommenes Sehen, Ohrensausen (Tinnitus)","Herzrasen, Brustschmerzen","Übelkeit, Bauchschmerzen, Mundtrockenheit, Durchfall, Verstopfung, Erbrechen","Kalter Schweiss, Hautausschlag","Verstopfte Nase, Halsschmerzen","Muskelschmerzen, Müdigkeit"],"sehrSelten":["Serotoninsyndrom","Extrapyramidale Störungen (Bewegungsstörungen, Muskelsteifigkeit, Sitzunruhe)","Synkope (Ohnmacht)","Halluzinationen, psychotische Störungen","Angioödem, Nesselsucht","Milchfluss (Galaktorrhö), Harnverhalt"]},"schwangerschaft":"Zu wenig Erfahrungen; während der Schwangerschaft nicht empfohlen, nur nach strenger ärztlicher Abwägung.","stillzeit":"Geht in die Milch über (Tierversuch); nicht stillen.","hinweise":["Regelmässig einnehmen – die Wirkung setzt erst nach 1–2 Wochen ein; zur Einnahme bei Bedarf nicht geeignet.","Ersetzt beim Absetzen von Benzodiazepinen nicht das langsame Ausschleichen.","Keine grösseren Mengen Grapefruitsaft trinken, Alkohol meiden; zu Beginn Vorsicht beim Autofahren."],"darreichung":["Tabletten"]},"busulfan":{"wirkmechanismus":"Zerstört blutbildende Zellen im Knochenmark, damit gespendete Stammzellen anwachsen können, und wirkt gegen Leukämiezellen. Busulfan ist ein bifunktionelles Alkylans (Alkylsulfonat), das DNA-Stränge quervernetzt und so die Zellteilung verhindert. Es wirkt besonders stark auf frühe Vorläuferzellen der Blutbildung. Abgebaut wird es in der Leber durch Kopplung an Glutathion.","nebenwirkungen":{"sehrHaeufig":["Schwere Knochenmarkhemmung (Neutropenie, Thrombozytopenie, Anämie)","Infektionen","Mundschleimhautentzündung (Mukositis)","Übelkeit, Erbrechen, Durchfall, Bauchschmerzen","Appetitlosigkeit","Erhöhtes Bilirubin und erhöhte Leberwerte","Haarausfall, Hautausschlag, Juckreiz","Fieber, Ödeme (Wassereinlagerungen)"],"haeufig":["Lebervenenverschlusskrankheit (VOD/SOS) mit Gelbsucht und Lebervergrösserung","Verwirrtheit","Dunkelfärbung der Haut (Hyperpigmentierung)"],"gelegentlich":["Krampfanfälle"],"unbekannt":["Lungenfibrose (Busulfan-Lunge) und interstitielle Lungenerkrankung","Herzbeuteltamponade bei Kindern mit Thalassämie","Zweitkrebs","Unfruchtbarkeit, vorzeitige Wechseljahre","Grauer Star (Katarakt) bei Langzeiteinnahme"]},"schwangerschaft":"Kontraindiziert. Frauen und Männer müssen während und bis 6 Monate nach der Behandlung sicher verhüten.","stillzeit":"Nicht stillen.","hinweise":["Die Hochdosis-Infusion erfolgt nur in spezialisierten Transplantationszentren, meist mit Spiegelmessung zur Dosisanpassung.","Zur Vorbeugung von Krampfanfällen wird vorher ein Antiepileptikum gegeben.","Paracetamol ab 72 Stunden vor der Behandlung nur nach Rücksprache einnehmen.","Bei Husten oder Atemnot – auch Monate nach der Behandlung – ärztlich abklären lassen."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung","Filmtabletten"]},"butamirat":{"wirkmechanismus":"Dämpft den Hustenreflex. Butamirat wirkt zentral auf das Hustenzentrum im Hirnstamm; chemisch ist es weder mit Opioiden noch mit Opium-Alkaloiden verwandt und hat kein bekanntes Abhängigkeitspotenzial. Zusätzlich werden eine leicht bronchienerweiternde und entzündungshemmende Wirkung beschrieben.","nebenwirkungen":{"selten":["Schläfrigkeit","Schwindel","Übelkeit, Durchfall","Hautausschlag, Nesselsucht"]},"schwangerschaft":"Im 1. Drittel nicht anwenden; danach nur nach ärztlicher Abwägung (keine ausreichenden Daten).","stillzeit":"Nicht bekannt, ob Butamirat in die Muttermilch übergeht; vorsichtshalber nicht anwenden.","hinweise":["Nicht gleichzeitig mit Schleimlösern einnehmen.","Nur kurzfristig bei trockenem Reizhusten; bei Husten länger als eine Woche, Fieber oder Atemnot ärztlich abklären lassen.","Kann müde machen – Vorsicht beim Autofahren, Alkohol meiden."],"darreichung":["Sirup","Tropfen"]},"butylscopolamin":{"wirkmechanismus":"Entspannt die verkrampfte glatte Muskulatur von Magen, Darm, Gallen- und Harnwegen. Butylscopolamin blockiert Muskarinrezeptoren an der glatten Muskulatur und in den vegetativen Ganglien der Bauchorgane. Als quartäre Ammoniumverbindung wird es aus dem Darm nur zu weniger als 1 % aufgenommen und gelangt praktisch nicht ins Gehirn; zentrale Nebenwirkungen wie bei Atropin oder Scopolamin sind daher kaum zu erwarten.","nebenwirkungen":{"haeufig":["Akkommodationsstörungen (Sehstörungen) (Injektion)","Schwindel (Injektion)","Tachykardie (Herzrasen) (Injektion)","Mundtrockenheit"],"gelegentlich":["Hautreaktionen wie Ausschlag und Juckreiz","Störungen der Schweissbildung (Dyshidrose)"],"selten":["Harnverhalt"],"unbekannt":["Anaphylaxie bis zum anaphylaktischen Schock, nach Injektion auch mit tödlichem Ausgang","Atemnot (Dyspnoe)","Blutdruckabfall, Hautrötung (Flush) (Injektion)","Pupillenerweiterung und erhöhter Augeninnendruck (Injektion)","Nesselsucht (Urtikaria)"]},"schwangerschaft":"Es liegen nur begrenzte Erfahrungen vor; vorsichtshalber in der Schwangerschaft vermeiden bzw. nur nach ärztlicher Abwägung anwenden.","stillzeit":"Ob Butylscopolamin in die Muttermilch übergeht, ist nicht ausreichend untersucht; Anwendung in der Stillzeit nicht empfohlen.","hinweise":["Dragées unzerkaut mit Wasser einnehmen.","Ohne ärztlichen Rat nicht länger als einige Tage anwenden; bei unklaren, starken oder anhaltenden Bauchschmerzen ärztlich abklären.","Nach einer Injektion kann das Sehen vorübergehend gestört sein: bis zur Normalisierung nicht Auto fahren."],"darreichung":["Dragées","Injektionslösung"]}});
